(function(r){const data={"id":"jiang-teacher","version":"20261104-catalog-3","name":"蒋老师","sources":[{"id":"jiang-001","title":"西湖边卖糖果","text":"我是1982年从学校毕业以后走上社会的，那一年就业形势相当严峻，我又不想在家待着，于是就让我爸妈想办法找到了一个营业员的临时工作，在西湖边上的一家食品商店站柜台卖糖果。\n来买糖果的顾客，有的是年轻父母，有的是祖父母带着孙辈，有的是天南海北来杭州游玩的游客。我喜欢小朋友，卖糖果的时候总是喜欢逗逗他们，一天的工作下来一点都不觉得劳累，特别开心。\n我的师傅姓俞，还是杭州市商业系统的劳模，她教会了我很多技术和经验，闲暇之余经常和我聊家常，我忙不过来的时候她会过来帮我一起干活，还帮忙捆扎游客购买的大宗商品，工作间隙师傅和我一起欣赏西湖边的美丽风景，哼一首小曲儿，记得当时流行《甜蜜的事业》\n电影插曲——“甜蜜的工作甜蜜的工作无限好罗喂，甜蜜的歌儿甜蜜的歌儿飞向天罗喂……”\n我们这个工作也真的是甜蜜的工作，糖果香甜可口，给顾客带去的是欢乐和杭州的温情，温暖了无数游客和孩子的心，虽然辛苦但非常有自豪感和满足感。\n三个月后，我由于找到了另一份工作而不得不和商店告别了，很不舍俞师傅和工友们，四十多年一晃而过，商店也早已不在了，师傅也应该八十高龄了吧？但这首甜蜜的歌曲，永远回荡在我的心里，久久不能平静。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"001_西湖边卖糖果.docx","sourceHash":"b5a2d54a85e14a75dc652a20d147524945c72c67fad357706120658c4be70e55","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-06 17:33:47"},{"id":"jiang-002","title":"浣纱河填平","text":"我1966年11月出生在杭州市上城区一个普通工人家庭，当时的房子在浣纱河边上，两旁都是老式民居。\n文革时期，“四人帮”和林彪江青的极左路线干扰，让国家贫穷落后，人民生活水平很低，小平同志第一次复出，排除极左路线干扰，提出来了实现四个现代化的宏伟目标，要实现经济恢复，大干一场社会主义现代化建设，大家都很欢欣鼓舞，随着中美破冰，经济建设也慢\n慢走上正轨，国家手里有钱了，市政建设也开始提上了日程。\n1973年市里决定老城区改造，浣纱河被填平改了宽阔的浣纱路，居住和出行环境大大改善了，有了饭馆，旅社，还建起来了新式楼房。电影院，杭州剧院，湖滨商业街都慢慢建成，杭州在慢慢好起来了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"002_浣纱河填平.docx","sourceHash":"cea4620fd70680849bc207f97f62c58ae17195434ed5da836aad4bb4ba36f78c","chapterNo":1,"stageId":1,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-06 22:55:03"},{"id":"jiang-003","title":"骆老师笃栗子","text":"小学时代我记忆深刻的就是我饮马井巷小学班主任骆红英老师。我没有上过幼儿园，汉语拼音一点都不会，田字格也不会写。开学第一天就被她骂了一顿，还挨了一个打，一个轻轻的头顶笃栗子……嚎啕大哭一场后的我，在全班出了丑。\n从此以后我发疯一样的学语文，上课认真听讲，课后作业认真完成，学期末考试全班第一。骆老师大喜过望，从此以后她始终如一视我为嫡传弟子，语文课代表这个职务一直当到小学毕业。\n这个简单粗暴的骆老师，竟然是我求学生涯最好的启蒙老师，也是被我奉为亲娘一样的恩师，可惜不知道老人家的近况如何？可安在？","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"003_骆老师笃栗子.docx","sourceHash":"89143658dcb5c2d38bc6c896403433e5875272cbddc93bdb30301102d615e557","chapterNo":1,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-07 17:02:39"},{"id":"jiang-004","title":"父亲与正路","text":"我爸爸和我一样都是杭四中的校友，他是1956年的毕业生，本来可以参加高考的，但是一场突如其来的肺病让他错过了高考，后来进了工厂当电工，文革前的老高中生在当时是文化人，他学习能力强，文化水平高，从普通员工做起，最后成为计量工程师，负责衡器计量\n室。\n我爸爸的成长经历也影响了我，他从小就对我和我妹妹严格要求，无论学习，工作，还是家庭，都要好好的靠自己。我也是从一线工人干起，最后成为质量专业人员，担任管理工作，我妹妹大学毕业后在外资公司担任高管。\n那个年代走歪路的年轻人很多，同学朋友中有刑拘的，判刑劳改的，我们两个都没有，始终如一的实践着正路做人，踏实做事的目标。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"004_父亲与正路.docx","sourceHash":"579877ab67ca793bb47c60dfbd0d427ba0be6003cb8b01ecda03c8324f210f4a","chapterNo":5,"stageId":1,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-07 19:00:16"},{"id":"jiang-005","title":"杭四中与质协证","text":"我记忆中最高光的时刻有两个，一个是考上了重点中学杭四中，还有一个是考到了中国质量管理协会颁发的全面质量管理电视讲座毕业证书。\n当时考上杭四中是百里挑一，文革结束后很多小学生相当于文盲，能够考上省重点杭四中的人真的是凤毛麟角，真的是感谢母校饮马井巷小学和南山中学；中国质协的证书，我同班同学中有很多有高工职称的同学都考试翻车，考卷是中国质协和日本专家联合出题，的确是难\n倒了很多考生，我一个青年工人却拿到了高分，厂领导都对我竖起来了大拇指。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"005_杭四中与质协证.docx","sourceHash":"03a4b62477ad37ae2107860d308c818248894d10aebecc65ac5e1547986e7d53","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-07 19:09:32"},{"id":"jiang-006","title":"排气操作工","text":"我是1982年底考进了我父母的单位杭州电子管厂当工人的，先在厂职工学校由高级工程师组成的教学组授课，学习电真空器件制造工艺学，然后下车间参观，最后被分配到三车间排气小组担任排气操作工。\n当时的工作服是白色大褂，车间的环境也非常的清洁。我们说它的确是非常好的高科技企业。\n带我的师傅是党员，还是先进工作者，又是班长。我在她的教育下，非常积极努力的学习技术，很快就通过了考试。\n排气是电子管生产最重要的工艺流程，技术要求很高，工作的责任重大。我积极学习技术，尊敬师傅，很快被评为优秀学徒，提前转正，成为三级工，第一次拿到四十二元五角的高薪。我师傅说我的工资比她都高。\n当时记得好像是给我奶奶还是外婆，可能是外婆吧买了礼物，然后又给父母一部分零花钱，基本上都上交了，自己只留了大概10块钱。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"006_排气操作工.docx","sourceHash":"c7c0644ee5719d6ab2fcb746f9eb257d858ad197fa6e16f0f900ce92dd0e352f","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-07 19:30:44"},{"id":"jiang-007","title":"1988年车祸康复","text":"1988年的时候我因为上班路上的一次车祸造成了右手臂肘关节粉碎性骨折，在医院住院治疗。\n当听到医生说我有可能会和周总理一样留下终身残疾的时候我非常震惊和害怕，我怕自己会成为残疾人，我热爱我的工作，我还没有女朋友，人生才刚刚开始。\n幸好我父亲的一位老朋友周炳辉教授，是中医学院骨科专家，他看了我的片子后说放心，你来我这里做手法复位和中医康复理疗，保证你不留残疾，重新回到工作岗位。\n手法复位非常疼痛，据说是比生孩子还要痛，周教授一次性成功了，夸我特别勇敢。\n中医康复理疗是中药熏洗，我妈和我妹妹一起帮我，终于在一个月后复查所有关节功能完全康复，除外形稍稍有点难看以外和正常人一样。\n周教授夸我创造了医学上的奇迹，勇气可嘉！\n从这次意外事故以后，什么困难都吓不倒我了。\n还有一个就是爱妻的离去，是重大的打击，人到中年，孩子渐渐长大，即将迎来好日子的时候，妻子小芬却病倒了，手术后恢复得不好，没过多久就离开了我们。\n中年丧妻，是人生的重大打击，办完后事，生活还是要继续，熬过了最痛苦的日子后，重归单身生活，重新适应单身生活，很困难，但也要过这一关，咬牙也要坚持下去。\n孩子们大学快毕业了，我也实现了对小芬许下的诺言，两个小孩都考上了大学，女儿学设计，儿子学建筑，专业不错，前途一片光明。\n退休后的生活，也是很有乐趣，文学，摄影，电影，音乐……陪伴着我也不一定孤单……开开心心每一天就好","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"007_1988年车祸康复.docx","sourceHash":"2f708d090a96d58486d2f3817d1099a7866b7141d6c7da0e571999c75502f4cb","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-07 22:06:52"},{"id":"jiang-008","title":"小芬来我家","text":"二十多岁的时候，曾经喜欢过两个女孩，一个是同事，一个是同学，两个姑娘都很好，可是同事喜欢大叔，最后成为大叔的老婆，同学嫌我是工人，地位低，最后也被迫分手……两场恋爱受挫，的确是心灰意冷，发誓要单身，潇洒走一回了，真爱不值钱，感情被戏弄，女孩\n啊，不值得被爱……\n看着我一下子跨过了三十岁大关，我爸妈急了，我妈托了她的小姐妹给我物色对象，于是她小姐妹的徒弟小芬，来我家见面了。\n小芬这姑娘真不错，长得漂亮身材又好，特别是脾气好，温柔善良，她的笑容特别自然，第一次见面就感觉挺顺眼的，我就和我妈说，就是她了……\n一年后我们喜结连理，又一年后迎来了一对龙凤胎，儿女双全，家庭美满，这大概就是爱情最美的样子吧哈哈","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"008_小芬来我家.docx","sourceHash":"aa980984bb4295dbf8537ca02f31ce9c640e2d9b919acb88b22cbdd2469c353d","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-08 08:18:36"},{"id":"jiang-009","title":"养大两个大学生","text":"这辈子我最骄傲的就是养大了两个儿女，双双成为大学生，没有什么惊天动地的大事，平民百姓，只求家庭和睦，平平安安，健健康康的，就好了。\n孩子们身体健康，有知识有文化，能够为社会做贡献，就是我教育的大目标。我家书香门第，我和我爸也都是普通的知识分子。我爸是计量工程师，我是质量管理人员。\n我们父子从来没有忘记自己是工人阶级培养的知识分子，也是这样教育孩子们的，不能忘本。\n有了知识文化也不能忘记自己是工人阶级出身，知识要奉献给劳动人民，要和工农兵打成一片，尊重劳动人民，这就是中国知识分子最重要的根基，离开了劳动人民，你再有知识也啥都不是。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"009_养大两个大学生.docx","sourceHash":"8e20eddf5b6e2c2c842835b0ed596a9029955da8e95b2ab1b2a5818e514bf14b","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-08 10:06:37"},{"id":"jiang-010","title":"文革教训不能忘","text":"我这代六零后，经历过毛泽东，华国锋，邓小平，江泽民，胡锦涛，习近平时代，经历过文化大革命，拨乱反正，改革开放，现代化腾飞，改革开放新时代。\n亲眼目睹了毛主席逝世，唐山大地震，粉碎四人帮，小平同志复出，中美建交，邓小平访美访日，港澳回归，北京亚运奥运，海湾战争，亚洲金融危机，巴塞罗那奥运会，海峡两会新加坡谈判，等重大历史事件……\n对革命和建设，改革开放，有特别深刻的认识，人不能走错路，国家更不能走错路，文化大革命的错误，让我们错过了世界经济起飞的二十世纪七十年代，幸好华国锋叶剑英两位老帅把四人帮打倒挽救了国家，小平同志又带领我们走上了中国特色社会主义的正确道路，改革\n开放，奋发图强，才有了现在的繁荣昌盛发达现代化。\n要好好学习世界上先进国家的发展经验，结合优秀传统文化，继续努力奋斗，实现两个一百年的奋斗目标，中国梦是一定会实现的，文革这样的噩梦不能再来，要好好总结经验教训，极左，极右，都极其有害，改革开放，两手都要硬，才是硬道理。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"010_文革教训不能忘.docx","sourceHash":"ecf37ec2e431a70a4f6dcd1ba20e29061518becce6e6295e7f9a41a6334ffa66","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-08 10:21:01"},{"id":"jiang-011","title":"崭新名字","text":"我的名字是我爸取的，当时文革时期破四旧立四新，老爸就说叫“崭新”好了。\n当年的文革色彩名字有很多，什么“卫东”，“红卫”，“强国”，“立新”……那个年代崇尚极致的红色，极左色彩浓厚，革命极为神圣，“灵魂深处闹革命”，衣服也是一片蓝一片红，否则就是资产阶级思想。\n现在想来的确是有点荒唐可笑，思想被禁锢，色彩被打压，这是非常窒息的年代，极左路线连人们的服饰都要控制，取名都要带上政治意味，这个“文化大革命”简直就是灾难！\n好在1976年10月的党中央逮捕“四人帮”的伟大转折，结束了这段荒唐而又无知的岁月，不然民族会被耽误到什么程度不得而知啊！\n1976年的10月，当得知粉碎“四人帮”的消息后，全国人民敲锣打鼓走上街头，欢庆人民的胜利，党的胜利，喜气洋洋，华主席叶副主席登上天安门城楼检阅庆祝打倒“四人帮”游行队伍的时刻举国欢腾，改革开放的春天到来了，全党全军全国人民将迈开步伐奋进在\n建设四化的道路上，这是多么鼓舞人心的时刻！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"011_崭新名字.docx","sourceHash":"b62f36e2b572b46fd203f910d0442c468927744f875cd65cd1ed9e8f41825bca","chapterNo":1,"stageId":1,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-08 12:11:32"},{"id":"jiang-012","title":"龙凤胎早产","text":"我有一对双胞胎孩子，龙凤胎是很稀奇的，还是早产儿，抚养也是千辛万苦，好在节衣缩食过日子，也慢慢的长大了。\n两个孩子都很懂事，也很聪明孝顺，学习成绩也不错。姐姐比较早熟外向，弟弟沉默寡言但比较内敛。两个人在一起偶尔会吵架，但最后还是弟弟让着姐姐。\n他们的到来让家庭充满欢乐，也充满了希望。现在也已经二十岁出头，正值好年华。他们的路还长着呢，希望他们身体健康，平平安安！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"012_龙凤胎早产.docx","sourceHash":"e8fdeeca6c7deb635456e4f43f1cef1f040a009d6a43413ba9032bcd7d9576ea","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-08 12:19:54"},{"id":"jiang-013","title":"没参加高考","text":"回顾学生时代，最大的遗憾是没有参加高考，因为偏文科，理科很差，所以参加高考希望不大，也就没有报考，高中读完就走上社会参加工作了。\n我大概也是运气好，由于学区好，小学进的都是好学校，百年名校，饮马井巷小学始建于清末，是上城区老牌名校，初中一年级就读南山中学，是百年名校杭州师范大学附属小学的前身南山二小的初中部，师资力量雄厚，文化积淀深厚，虽说是文革时期但底子还在，老师也\n认真负责，所以小学的文化底子我还是很扎实的，一路顺风又考进去了百年名校杭四中。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"013_没参加高考.docx","sourceHash":"d37ba4baff2171c4e86d8d8cfa2c1556673f86fedefa47595db8b7f299d501cd","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-08 14:36:28"},{"id":"jiang-014","title":"杭州电子管厂","text":"能够走上电真空器件制造这条路，还是要感谢杭州电子管厂，这家电子工业部定点的国二级企业，技术力量雄厚，职工素质高，我在一线工人的岗位上得到了非常扎实的锻炼，培养了动手能力，熟悉了所有产品的工艺流程，为今后从事零部件质量管理打下了很好的基础。\n很感谢我的师傅们，排气启蒙师傅王教珍、朱玉余、戴艳秋，工艺启蒙师傅童桂福、王德进，管理启蒙师傅袁晓。这些老师傅不仅教会了我技术，更教会了我人品，严谨求实，踏实做事，老老实实的干好事业，受益终身。他们如父母一般，让我在技术和经验上得到了进步。\n如今他们都已八十多岁了，我这个徒弟还是没有忘记他们，师傅教诲，永记在心！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"014_杭州电子管厂.docx","sourceHash":"41b10c4003a6597eab4f0a5db6f98d507535d76e7c635e42649b758f52679a40","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-08 14:48:33"},{"id":"jiang-015","title":"杭州电子管厂","text":"电真空器件在当时是一个高技术行业，上世纪五十年代在大跃进的洪流中杭州市准备发展电子工业，由市委牵头，杭州富春江电讯器材厂和几家小企业合并成立了杭州电子管厂，并在南京和上海两家电子管厂的支援下开始生产电子管产品。\n当时的电子管理论基础是苏联的电子管教材和技术资料，采用的标准是苏联标准，汞气整流管、放电管、高压整流管，都在艰苦的条件下生产出来了。\n六十年代又引进了上海的X射线管生产线，七十年代初又开发了军品，杭州电子管厂成为了电子工业部定点生产电真空器件的专业工厂，全盛时期有职工一千多人，拥有大面积的厂房和完善的配套设施，产品质量优良，拥有自己的电真空器件研究所，可以开发全品种的电子\n管，这在当时是非常了不起的。\n能够成为这样的工厂员工，是非常自豪的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"015_杭州电子管厂.docx","sourceHash":"5bcc403b5d320471b14a6c12d7c2fea4ecc3d79870b1284d7e1c8786e5e92845","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-08 15:02:45"},{"id":"jiang-016","title":"1977年电视","text":"1977年，改革开放的序幕拉开，由于和西方国家的关系改善，美国日本的电影进来了。\n记得当时北京电视台播放日本故事片《追捕》《望乡》《狐狸的故事》，美国电视剧《大西洋底来的人》，那叫一个万人空巷。\n电影里面的繁华东京，高楼林立，高速公路车流滚滚，人们衣着入时，生活富裕；美国先进的科学技术，探索海洋世界。\n世界打开了，耳目一新，原来在二十世纪七十年代，人家都已经进入到发达国家阶段了！\n而同时期的我们在干什么？荒唐的文化大革命，造成了空前绝后的浩劫，人民生活贫困，国家发展停滞……再也不能这样下去了！\n“以阶级斗争为纲”，荒唐绝伦，党中央及时作出的改革开放建设社会主义现代化强国的决策，把工作重点转移到经济建设上来的号召，非常及时和正确，这使我们抓住了七十年代末发达国家转移技术和产业的机遇，为后面的大发展奠定了基础。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"016_1977年电视.docx","sourceHash":"da6a84d8c968b662263e71a1c9df92f4cca83058a966ea45fc7b6554ca3589e2","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-08 15:17:47"},{"id":"jiang-017","title":"1999学计算机","text":"1999年，我为了提高自己的技能，想多学一点知识，工余时间报名读了计算机应用能力培训课程，从零开始学习计算机。\n由于英语基础好，理解能力强，顺利的拿到了合格证。\n现在看来，这个决定受益匪浅，它让我跟上了信息时代，没有成为信息文盲。\n现在计算机，智能手机，穿戴设备，我都能应用自如，老年人当中我也算是厉害的了。\n人工智能时代来临，我又下载了AI软件，可以智能作曲，写文章，查资料……\n老年人不能和社会脱节，要跟上时代潮流，才能活得开心，活得精彩！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"017_1999学计算机.docx","sourceHash":"5077c053b8321ceb9576196174c723766be2328e2c35438bb8c98a887c0b65e4","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-08 15:27:32"},{"id":"jiang-018","title":"在家看《跟我学》","text":"1982年社会上掀起来了学英语的热潮，我们中学生也不甘落后，跟着电视学英语。记得当时央视引进了英国BBC的电视英语教学片《跟我学》，播放以后轰动一时，教学效果非常好。\n里面的两位英国老师，男的叫弗朗西斯，女的叫凯瑟琳佛拉瓦，一个潇洒英俊，一个温柔漂亮，标准的伦敦腔英语，非常好听。我们被迷住了，看两位老师的美貌同时不知不觉中也把英语学好了。\n当时我是在家里看的电视。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"018_在家看《跟我学》.docx","sourceHash":"08021f3ad51e83660abfdf58eb4d18bddf5aa54386f0c67901c404249f641740","chapterNo":2,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-08 15:41:19"},{"id":"jiang-019","title":"西湖牌照相机","text":"我的收藏事业是在退休后慢慢开始的。\n从小就喜欢照相机，先是用胶片傻瓜机，给老婆拍，给孩子拍。照片拍多了就想收藏相机，这几年一直在二手市场买相机，前前后后加起来差不多十来部吧，有胶片单反，胶片傻瓜机，数码单反，数码旁轴。\n最值得珍惜的就是全杭州没有几部的西湖牌照相机，除了高氏相机博物馆的那台和苏州一位藏家的一台就是我这台了。\n相机是文化，可以流传后世的，我也想继续收藏这些珍贵的记忆，让年轻人知道相机文化。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"019_西湖牌照相机.docx","sourceHash":"5d984c3596a1784d95924a670a244f040cf23eb062a3bdefbf918bd5b91c5638","photos":[{"id":"jiang-photo-019","url":"v17/assets/jiang-teacher/019-image3.jpg","name":"故事卡所附西湖牌相机资料图","caseReference":true}],"chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-08 21:37:15"},{"id":"jiang-020","title":"八分钱看电影","text":"电影也是我特别感兴趣的爱好，从小就喜欢看电影。\n上世纪的小学时代我奶奶就每周给我八分钱一个人买电影票看电影，当时看过很多革命样板戏、文革题材电影。\n工作以后看的国内外电影就更多了，前前后后加起来差不多几千部。\n大概我在杭州也是最早使用DVD机的人，结婚的时候我买了一个国产DVD机，专门用来看电影，每个周末晚上是我和老婆小芬最开心的电影时间。\n电影让我们夫妻感情更好更融洽，这个爱好也遗传给了孩子们，他们也是电影迷。\n现在我的电影收藏已经有几千部了，载体也从DVD光盘升级到蓝光光盘和网络下载，还在不断增加中。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"020_八分钱看电影.docx","sourceHash":"23c2eca5ce8e2616f9e618aa2c6ffdc78b8b97e4da93df64bff7c36ff53eaf3f","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"CHILDHOOD","recordedAt":"2026-08-08 21:49:23"},{"id":"jiang-021","title":"军品电子管","text":"1999年发生的北约轰炸中国驻南联盟大使馆事件，举世震惊，我们职工也不例外感到义愤填膺，使馆是国土，被轰炸等同于侵略，但当时我们军事力量单薄，无力反击，只能选择隐忍。\n这件事情告诉我们，只有国力强大了，有足够的反制手段，才不会被别人欺负，中国一定要有自己的国防现代化，才能保证国家安全，领土完整。\n全厂职工在厂党委的领导下，团结一心，拼命也要把军品电子管拿出来，为国防建设做贡献。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"021_军品电子管.docx","sourceHash":"e38e2776c3836299a15dcfbc5b9a80d4fba40b794b5bd3dcff90c0640d76f378","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-09 09:39:09"},{"id":"jiang-022","title":"骑车夜校三年","text":"六零后是中国最勤劳的一代人，文革结束后最早投入中国现代化建设就是我们，我们继承了父辈的吃苦耐劳不畏艰辛的精神，八十年代初工厂企业都只有单休，逢紧急生产任务都要加班，但大家都是毫无怨言主动上班放弃休息，因为时间不等人，四个现代化不是坐而论道是\n要实干出来的，年轻人白天上班晚上读夜校是常态。\n我1983年考入了钱江业余学校英语大专班，白天上班，晚上骑车去上课，班里的同学都来自五湖四海，有的是工人，有的是教师，有的是医生，还有浙大的老师来学英语，学习气氛浓厚，我也认识了很多新朋友。\n三年之后大家毕业各分东西，也不知道他们近况如何，很想念这些同学们！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"022_骑车夜校三年.docx","sourceHash":"77f18d03ba61e86d155e71557090b003d626b831bf0710fe67dad79cd597849c","chapterNo":2,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-09 09:50:30"},{"id":"jiang-023","title":"鱼有鱼路虾有虾路","text":"1983年前杭州的生活水平还是很低的，贫穷落后，当时港澳台比我们要富裕很多很多。\n那个时候住的房子破破烂烂，吃穿用都普遍很差，收入很低，出门都是步行，公交，自行车最多，人口多的家庭，衣服都是新三年旧三年缝缝补补又三年，弟弟妹妹穿哥哥姐姐的……不甘于现状的脑子灵活的，都想到港澳台或海外去见见世面，赚点钱……\n当时家里只要有点海外关系的人都想尽办法去外面打工或者定居，我的同学当中就有很多人利用各种渠道去了国外和港澳台。\n当时我们朋友当中还有人勾搭外国老头子嫁到日本美国的，没办法，太穷了，只有鱼有鱼路虾有虾路出去了。\n没想到的是四十多年过去了，中国成了世界上仅次于美国的第二大经济体，进入了中高收入国家行列，于是这些人又想鱼有鱼路虾有虾路回来了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"023_鱼有鱼路虾有虾路.docx","sourceHash":"a6cee771de413fcd88dbbc55da47a7b1cba58f339c976b986d03bdefb9edce79","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-09 10:05:21"},{"id":"jiang-024","title":"四十多年路","text":"我这一辈子人生，还是感到很值得，也很满足，经历过贫穷落后，也经历过改革开放，经历过各种挫折，也经历过欢欣鼓舞……\n现在的国家繁荣富裕，也是通过自己的艰苦奋斗得来的，这段路我们是用四十多年完成了发达国家几百年才能走完的路，这是人类历史上最伟大的路，也是最艰苦的路，死了多少人也无法计算，所以要格外的珍惜今天。\n这四十多年走完的路，也难免会遭人妒忌，会有人恶意中伤，会有人明里暗里算计你，什么贸易战，思想战，能源战，都使出来了……但我们不能怕，要敢于亮剑，敢于斗争，才会巩固胜利成果，取得更大的胜利！\n希望后辈努力自强，提高自己的战斗力，继承父辈的精神，继续把强国富民的道路走好走扎实，这就是我最大的心愿……","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"024_四十多年路.docx","sourceHash":"e71694a85712d88c94388184a7edcddf3854970972c3823d00f6175066b59bdf","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-09 10:20:25"},{"id":"jiang-025","title":"六灯收音机","text":"改革开放前的六七十年代，人人都是中山装人民帽解放鞋，女人穿女式列宁装，顶多扎个辫子，烫个发会被打成资产阶级生活方式。孩子们的衣服都是补丁打补丁，弟弟妹妹们穿的都是哥哥姐姐穿过的旧衣服。\n家里除了家具以外没有任何家电，我家当时有一台电子管六灯收音机就算是富裕家庭了。\n工人月薪十元二十元已经是高薪阶层了，医保福利待遇比较好，看病可以凭特约记账单在医院报销，但这个待遇只有少数全民所有制国企才有。\n那个时候家里有辆二八大杠自行车就算是富裕阶层了，手上戴个国产上海牌手表，穿件的确良衬衫，骑二八大杠自行车的小伙子，会很快得到姑娘的青睐谈恋爱。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"025_六灯收音机.docx","sourceHash":"8686fb22bfb34119dfeacc9056e344dc1c44dc7edc7b044cffba33f2ea8687ff","chapterNo":10,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"CHILDHOOD","recordedAt":"2026-08-09 15:46:40"},{"id":"jiang-026","title":"引进西门子生产线","text":"发展是硬道理，只有发展才是真的社会主义。\n二十世纪七十年代末我们终于抓住了发达国家向发展中国家转移落后产能和劳动密集型产业的机遇，开始引进外资，开经济特区，生产力高速发展，改革开放终于走上了快车道。\n杭州电子管厂也抓住了机遇，和西德西门子公司谈判引进了先进的旋转阳极X射线管生产线和全套技术设备，还签订了更先进的高速旋转阳极X射线管全套技术诀窍转让合同，工厂一跃成为全国同行业技术最先进质量最优秀的企业。\n职工的收入也成倍增长，到1988年底，职工家庭人人都有了彩色电视机，电冰箱，洗衣机，自行车，小康生活真的实现了！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"026_引进西门子生产线.docx","sourceHash":"e48690fcb0629707c1573b40d17e8eaafa3fc8982d4a851f5835028b0a2065ba","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-09 15:59:38"},{"id":"jiang-027","title":"庄工与柳浪闻莺","text":"我的朋友当中，老同学庄文澜工程师算是知心朋友了，从高中开始到现在，一直交往不断。\n他在电视机厂工作，也和我一样从一线工人做起直到成为质量管理人员，也许是同行吧，所以共同语言特别多。\n他一直没有成家，孤家寡人的也特别值得同情，所以我时常邀请他到家里来玩，周末一起去约个饭，状元馆吃面，去公园走走看看拍拍照，柳浪闻莺，吴山广场。\n他的个人条件比较差，所以看上他的姑娘很少，其实他人挺好的，聪明能干，就是嘴笨，人相貌差了一点。\n长期的单身和抑郁，让他的健康出了问题，住院治疗不久就病逝了，失去了这位挚友，我很难过，希望他在天国安好。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"027_庄工与柳浪闻莺.docx","sourceHash":"8e368af2939ec69c040ad57fa2c6aad421267aa936435d85941b6a2eb2240744","chapterNo":7,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-09 16:25:17"},{"id":"jiang-028","title":"1981女排夺冠","text":"1981年11月份，世界杯女排赛在日本东京代代木体育馆举行。\n我们全家在家看电视转播。那台黑白电视里，以张蓉芳为队长的中国女排在教练袁伟民带领下七战七捷，气势如虹地站上了冠军领奖台。\n最后和日本女排的较量扣人心弦，日本女排在小岛孝治教练的指导下也十分顽强，但中国女排以惊人的毅力战胜了日本，拿到了冠军奖杯。\n目睹国旗升起的一刻无比的激动。这场历史性的比赛震动了全中国，人们为中国女排欢呼，“顽强拼搏，为国争光”的中国女排精神，一直到现在都闪耀着时代的光芒。\n作为排球爱好者，这场经典比赛的录像我一直珍藏着，不时回味一下，女排精神，永远值得珍惜和回忆，激励我们在新征程上不断奋进。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"028_1981女排夺冠.docx","sourceHash":"3cdb93cc566233429e44ef4f4c5d3e3d490b7c5a6f2ed220ef4310e9c6f08bce","chapterNo":6,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-09 16:41:24"},{"id":"jiang-029","title":"南山操场颁奖","text":"童年最快乐的一天是1978年六一节傍晚在南山中学的操场上举行的庆祝中考成绩大会。\n金平一校长亲自为我们这些考上了杭四中的同学颁奖，奖品是一支钢笔和四本练习簿，勉励我们在即将到来的新的中学时代好好学习天天向上，我们系着红领巾向金校长敬队礼。\n当年的温馨场面令人动容，一辈子都难忘。如今金校长已仙逝，我们这些同学还和他女儿小金保持着联系，怀念着这位慈爱的老校长。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"029_南山操场颁奖.docx","sourceHash":"9efda8f1b9d297bfe4d57414d0971a45f4842cd5f2bd4a00ff5c58fa9be95d86","chapterNo":1,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-09 16:55:26"},{"id":"jiang-030","title":"ISO9000培训","text":"2000年，我所在的企业要引进ISO9000质量管理体系，于是公司选了包括我在内的一批人去系统培训。\n这个培训班是我历史以来最难的培训，老师讲的内容，我们就好像在听天书一样，没办法，生吃萝卜一样的听课。最常卡在‘质量方针’这个概念上。\n无奈之下，我们只能是课外找资料，从名词解释开始学起，好比小学生学写字一样的慢慢消化。\n功夫不负有心人，苦学还是有回报的，考试考完了大家都得到了合格证，我的这张考卷还被生产部经理拿去做了标准答案，在公司内部使用。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"030_ISO9000培训.docx","sourceHash":"fd3eec6ee3639903215bf47a17ebd8dc18ecd7bd93fa4af3f91f88d51044f93b","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-09 17:12:02"},{"id":"jiang-031","title":"TQC考试","text":"对于质量管理这个问题，在改革开放之前是没有什么概念的，我国正式引入这个体系，是八十年代初，从日本东芝、日立、丰田等大企业的TQC标准开始的。\n1985年中国质量管理协会和中央电视台联合举办了电视讲座，供国有企业管理人员系统学习日本先进的TQC标准，我厂也立即组织了讲座的学习，抽调了优秀的高级工程师、技术员、有一定文化基础的青年工人来系统的学习这套教材，我有幸成为其中一员。\n在会议室的听课中，我认真听讲，记下来了厚厚的笔记，逐字逐句的理解所有的概念和理论，闭卷考试的试题非常难，而我凭着自己最大的努力百分百完成了答卷，取得了九十多分以上的高分，拿到了结业证书。\n有趣的是有三名高级工程师同学没有通过考试，也是非常遗憾的事情，不是说他们不努力，是年纪大了记忆力差了，英语又不太过关，理解就欠缺了一些，这些复杂的理论，对刚刚经历了文革的这些老知识分子而言的确是个难题。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"031_TQC考试.docx","sourceHash":"15e084758b29f2cc5e73f2725e540b3267e76e3089a71b5a7d3f9cd2cace9cf0","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-09 20:52:37"},{"id":"jiang-032","title":"海湾战争启示","text":"1990年夏天，伊拉克总统萨达姆·侯赛因悍然发动入侵邻国科威特的战争，在一天之内占领了该国，举世震惊。联合国安理会立即召开特别会议讨论海湾危机，并通过决议要求伊拉克立即从科威特撤军，但萨达姆拒不理会。\n经过多次外交调解无效，美国苏联罕见取得一致并交联合国授权美国组织多国部队采取军事行动把伊拉克军队赶出科威特。\n起初我们并不看好组织松散，兵员复杂，五十多国组成的多国部队，但是布什总统慧眼识英雄，任命久经沙场经验丰富的施瓦茨科普夫将军担任总司令，在科学组织，高科技武器，集中统一使用优势兵力的条件下，取得了完全的胜利，海湾战争顺利的结束了。\n这场战争，对我们这些年轻人来说就是不小的震动，原来战争可以这么打，高科技武器威力强大，地面战争只打了一百小时，多国部队只伤亡了数十人，而伊拉克百万大军被团灭。\n这对我们国家来说也是不小的启示，军事现代化要提上日程了，而这对我们工厂来说，提醒了我们企业的现代化改造也是必由之路，老旧设备替换必须加快速度了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"032_海湾战争启示.docx","sourceHash":"8edb8e4d2046992777ba2a5f88149c10a22e72abc345a4c0b2de0f0aa6a9ccee","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-09 21:17:41"},{"id":"jiang-033","title":"文化消费日常","text":"文化事业是国家经济发展以后必然会出现的朝阳产业，现在电影院，博物馆，文化馆，如雨后春笋一般涌现出来，这真是我们退休人员的福音。\n我喜欢看电影，听音乐会，看演出，参观博物馆、美术馆、科技馆，一顿顿文化大餐，丰富了我的退休生活，也开阔了眼界。\n我不抽烟，不喝酒，退休金除了贴补家用以外大部分都是花在了文化消费上了，买书买杂志也是消费的一部分。吃喝玩乐我不太感兴趣，文化消费我却毫不吝啬，花钱花的开心，有收获就好。\n旅游么，年纪大了远地方去不了就周边游，走走看看，也挺好，品品当地的美食，领略风土人情，这比单纯的吃喝玩乐有意义多了。也希望能认识更多的朋友，结伴同行。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"033_文化消费日常.docx","sourceHash":"48cb0b91985b8167bb36ac943e151f46ebe495b14556af3951ff3cf0ee5fcbe6","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-09 21:45:41"},{"id":"jiang-034","title":"批斗孔老二","text":"文革时期我做过的荒唐事，就是把两千多年前的平民教育家孔夫子揪出来批斗，当时读小学啥也不太懂，老师布置下来写就写了，以为这就是革命，就是斗争，是反对封建压迫的正义斗争……写过许多的批斗“孔老二”的大批判稿子，义正辞严的上台演讲。\n十一届三中全会以后，中央搞拨乱反正，孔老先生的历史也得到了澄清，原来他收学生是不收学费，不收家长礼物的，他乐于助人，收的都是穷人家的子弟，教他们学文化，要知礼节，重孝道，老先生传授传统文化不遗余力……有教无类因材施教原则就是他提出来的。\n当知道了历史上真实的孔老师是怎么样的以后，我无地自容，专门去了一趟孔庙，向老先生赔罪，请求他原谅我的幼稚无知。\n文革时期颠三倒四的事情还有很多，如“白卷英雄张铁生”，“反潮流小将黄帅”，“四人帮”上海干将陈阿大接见外宾不学无术闹笑话等等，都是我亲身经历过的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"034_批斗孔老二.docx","sourceHash":"82c3505cdba3bacdaf370af70dfe31a13dc38cd82d2aa4785e2af79a1075949e","chapterNo":2,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-09 22:10:55"},{"id":"jiang-035","title":"无为而治","text":"对孩子的教育和培养，我的经验是“无为而治”，我从来都没有把自己的观念强加给他们。\n女儿喜欢艺术，我鼓励有加；儿子喜欢电脑游戏，我也不一味禁止。总之就是让他们自由发展，热爱是最好的老师。\n在这个宽松的环境中，孩子们健康快乐地长大。女儿选择了产品设计专业，儿子选择了建筑工程技术，我觉得都挺好的。他们都有美术天赋，这两个专业也可以发挥特长。\n在孩子学习上，老婆小芬也没过多的干涉我的方针，这点我非常感谢她的认同和支持。孩子们的成长，也离不开她的悉心照顾和关爱。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"035_无为而治.docx","sourceHash":"ea677ed32915dbca28ad3b628d4bb67860dddb01d88066737f3521466f3b4c2d","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-09 22:27:25"},{"id":"jiang-036","title":"写回忆录","text":"啰啰嗦嗦说了这么多，该是收尾的时候了，人生其实很短暂，六十年就这样一晃而过了，我只是一个普普通通的人，普普通通的老百姓。\n但有些事不能遗忘，回味人生道路，就是要总结经验教训，更好的走好晚年，给自己和土地公公一个完整的交代，给后辈留点文化遗产，就是我写这个回忆录的目的。\n人啊还是要往前看，后面会怎么样我们不得而知，前面经历的事情要让后人知道，就是这本小册子的作用了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"036_写回忆录.docx","sourceHash":"076f1977a25d0ea0255e055825f842916e7781074050a7cde1d33eaef33744e9","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-09 22:36:43"},{"id":"jiang-037","title":"八分钱看电影","text":"说起电影的变迁，我也想多聊一会。上世纪七十年代的时候，我家就住新华电影院旁边，所以看电影不要太方便。我奶奶每周都给我八分钱让我周末去新华看电影，那时大概七八岁。\n那个时候都是胶片电影，一部拷贝有五六盘甚至七八盘胶片，由跑片员骑摩托车在各家电影院来回穿梭送片盘。有时候送晚了没接上，电影院就放幻灯片救急，等片子到了再继续放。\n跑片员的工作非常辛苦，但也非常受观众的尊敬，有热心的观众会给他们递烟送水，这些叔叔也非常的敬业。\n偶尔会有宽银幕电影上映，那视听感受就不一样了。记得那时有朝鲜电影《卖花姑娘》，彩色宽银幕，画面太美了，据说导演是金正日同志（金日成之子），艺术水平高，大家都看哭了。\n当时有句话说“越南电影飞机大炮，朝鲜电影哭哭笑笑，阿尔巴尼亚电影搂搂抱抱”，哈哈哈，总结得太好了。当时都只有社会主义兄弟国家的电影引进，资本主义国家的电影很少见到。\n到了八十年代，影片就丰富多彩多了，五大洲五湖四海的都进来了，欧美日，法德意，两个牙，台湾，香港，苏联，南斯拉夫，百花齐放。我也是乐在其中，尽享艺术盛宴，每周末基本上都是泡在电影院里乐不思蜀。\n票价也便宜，一毛五分钱的票价维持了好几年，后来才慢慢涨到一元两元。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"037_八分钱看电影.docx","sourceHash":"ddbfe0a3e557efc360b8127ca3b190ed3eb866024c2097539c4c8113a9bd2658","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"CHILDHOOD","recordedAt":"2026-08-10 09:24:48"},{"id":"jiang-038","title":"黑胶唱片机","text":"听唱片，也是文革时期萌生的爱好。记得当时弄堂里邻居马家姐妹，二十来岁，是高级知识分子家庭，她家有黑胶唱片机。\n每逢周末，马家姐妹就带上我和我妹妹一起去她家听唱片。当时我八九岁，妹妹四五岁。\n那个时候优秀的古典音乐被批为“大毒草”，马家姐妹在放唱片之前都要拉上窗帘关紧门窗，然后再放音乐，怕人家一听见要举报。\n记得当时听过的黑胶唱片有《梦幻曲》，柴可夫斯基的《天鹅湖》，拉赫玛尼诺夫的交响曲，李德伦钢琴独奏，俞丽拿小提琴《梁祝》。\n放完唱片，大家偷偷鼓掌，讨论音乐。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"038_黑胶唱片机.docx","sourceHash":"6483c39652cc7e2bb217837d37dd8817893b857efd3b2b1f25c86485a62c6dcd","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-10 09:38:25"},{"id":"jiang-039","title":"爸爸装电视","text":"1974年前后，社会上开始有黑白电视机上柜供应，全国各地开始试播电视节目，浙江电视台也在北高峰建设了电视塔。\n当时看电视都是到有罗马尼亚黑白电视机的邻居家蹭看，我们全家都是电视迷，这蹭看也不是长久之计，于是我爸提议他准备自己动手装一台九英寸黑白电视机，可以家里看。\n说干就干，我爸托朋友从上海买回来了全套星火牌黑白电视机套件和显像管，按照《无线电》杂志提供的星火牌电视机线路图，自己开始组装。我和妹妹打下手，帮忙递工具。不愧是老电工，松香焊锡电烙铁一齐上阵，万用表仔细测试，一台赤膊的电视机成型了。\n为了安全，我爸又到电料店买回来了电视机壳，安装完毕开始调试。\n当黑白格测试卡正常出现在面前，我们一片欢呼雀跃……成功了！那晚我们全家人围坐在一起看电视，新闻节目之后就放电影《碧海红波》，抗美援朝保家卫国的悲壮历史，志愿军雷达兵为战争胜利出生入死，印象深刻！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"039_爸爸装电视.docx","sourceHash":"0a5cedb58cad8828831cfbdb77b663c06345a1f8aa97ef2bbcd1a4415015b81b","chapterNo":5,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-10 10:00:26"},{"id":"jiang-040","title":"1988台风夜","text":"1988年8月8日，我妹妹生日，吃过晚饭，全家人一起吃蛋糕，品茶，在阳台上赏月聊天。\n凌晨时分，突然一场十二级台风伴着暴雨如注，惊醒了熟睡的全家人，狂风怒号，震碎了阳台的玻璃，我和妹妹死死顶住了阳台门，爸爸拿来胶带封住了，窗外大树被风折断，小区变压器爆炸，弧光蓝光还有闪电的白光，就像是唐山大地震的闪光，十分恐怖。\n台风的呼啸像世界末日一样。\n第二天早上起来，大树被连根拔起，横躺在路面上，电线杆子倒伏，一片狼藉，自行车上班是不可能了，公交车也没有了，只能走路到厂里，走路走了一个多小时。\n人们自发去西湖边上救树，部队也出动了，好几天才缓过来。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"040_1988台风夜.docx","sourceHash":"9b9fcaccdedfd647beb978d4fbbeaf0bd079b0cf18b3b0d542d442ef0e3cdc09","chapterNo":6,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-10 13:08:51"},{"id":"jiang-041","title":"西湖四季","text":"杭州是个好地方，适合退休养老，风景好，一年四季都是适宜旅游观光，能够生在杭州，是几辈子都修不来的福气。\n现在空了到处走走，带着单反相机记录西湖四季，累了找个地方歇歇脚，吃点东西，多少惬意。\n前半辈子的辛苦，能够换来现在的退休生活，很满足很幸福了。\n人生遗憾不是没有，一是没有参加高考，二是没有读过全日制本科，如果这两个当时实现，可能我的人生更加完美，命运可能会更加顺畅，但是人生就是这么不完美，就是希腊爱神不也是缺了一条胳膊么？\n这缺了一条胳膊的爱神在卢浮宫展览，大家都认为比两条胳膊的还要耐看，还要富有联想的韵味，是不是这样啊哈哈！不完美就是完美，过日子就是这样的，世界上哪有那么多十全十美，是吧？","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"041_西湖四季.docx","sourceHash":"50cf85db4765325d7b56b61c0a14c3d805ebada58d0fef702f4f4a3b56061200","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-10 16:40:18"},{"id":"jiang-042","title":"两熊公审","text":"1979年杭城还发生过一件惊天动地的大事，就是原浙江省军区副司令员，中央委员熊应堂将军的两个儿子熊紫平，熊北平，因为强奸、聚众斗殴、流氓罪被公审，一个枪毙，一个无期徒刑了。\n这在当时轰动了全城，浙江电视台实况转播了公审大会的实况，我们在家看电视，这两个作恶多端的“衙内”被五花大绑，哥哥被押赴刑场执行枪决，弟弟判无期徒刑，判决之重，公审之快，在当时是非常震撼人心的，中央委员的儿子，犯了天条也被问斩，人人都拍手称快\n，赞共产党公正廉明，执法如山！\n这在现在都是难以想象的，开国少将的儿子，因为流氓罪被问斩，可以想见两熊当时是多么的惊慌，听说他们听到审判长判处熊紫平死刑立即执行，熊北平无期徒刑的时候，当场大小便失禁了，屎尿一地……熊北平后来自杀死在牢里。\n从此以后，高干子弟再也不敢胡作非为，称霸一方了，法无禁地的概念，深入人心！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"042_两熊公审.docx","sourceHash":"5a8e41203fa64b74ae47db9fcacdb3eccb672fc3a6b2cfef2beb9555f14defa6","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-10 17:22:52"},{"id":"jiang-043","title":"1974年上课","text":"整个童年，经历过文革，拨乱反正，改革开放三个阶段。\n它给了我反思，教育，启示。\n缺了一个完整的受教育体系，因为文革干扰了整个小学教育，实际上没有读多少书。\n直到1974年才开始比较有规律的上课。\n1977年才懂得要好好学习，把“四人帮”的干扰破坏造成的损失夺回来。在南山中学的日子里，才开始发奋苦读，南山中学的金校长是大教育家，为我们创造了一个非常好的学习环境，我能够考上重点中学，全靠南山中学，非常感谢他老人家。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"043_1974年上课.docx","sourceHash":"969f530908562a19db7c9589a97c80cf7d19d121f93c5ef335a23678bfe01522","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-10 17:51:34"},{"id":"jiang-044","title":"烧玻璃学徒","text":"电真空器件制造是手工工艺，我当时跟师傅学艺，是从烧玻璃开始的，使用煤气火头烧结玻璃管，接玻璃排气管。\n刚开始的时候笨手笨脚，没有掌握好要领，师傅示范操作后轮到自己实践，却满头大汗烧不好。后来慢慢悟出来一定要多烧，熟悉玻璃的特性，让它像面团一样任我揉捏摆布就成功了。于是我每天都加班练习，付出了烧破三条裤子、烫伤一个手指头的代价才学会了。\n后来对玻璃工这个技巧特别感兴趣，又拜老师傅为师学会了氧气火头技艺，能够熟练地掌握封口、排气、调整工技术，成为一名一专多能的复合型技术工人。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"044_烧玻璃学徒.docx","sourceHash":"a90b2d61e0d87505cdd111df4c17306997594d1853a54bb06f059ae4a4737446","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-10 18:29:11"},{"id":"jiang-045","title":"阴极套阳极帽","text":"要做好质量管理工作，首先必须要精通整条生产线的工艺流程，熟悉所有产品，特别是零部件图纸和实物，这就离不开童桂福和王德进两位老师傅的悉心指导和培养。\n在工艺组办公室里从最基本的读图开始，到金加工的工艺，全套的产品图纸工艺文件，一一对应起来学习熟悉。童师傅王师傅毕业于南京无线电工业学校，先后当过排气工、工艺员，有丰富的经验和理论素养。\n在两位老师傅的教导下，我很快熟悉了岗位，可以独立完成工作了。由于读图和金加工工艺熟练了，还可以和金工车间的检验员互相交流，在零部件检验入库上把好质量关。\n他们还把多年积累的经验无私地分享给我：读图不是死读图，还必须要顺着设计者的思路琢磨准确的公差关系，找到合适的平衡点，以便在验收时和金工车间有讨论的余地，该返工的返工，该报废的报废……这些宝贵经验，都是现场工作的依靠。\n这些东西我到现在都没有忘记，现在只要一看到电子管图纸，就会出现脑海里的阴极套，阳极帽零件形状，哈哈。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"045_阴极套阳极帽.docx","sourceHash":"cffd874e936b6f2d0bb4e5c271261b593d6aaddeceedf545d661e7faad784eaf","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-10 21:34:32"},{"id":"jiang-046","title":"1985年应征证","text":"1985年4月，国防部、中央军委决定恢复公民兵役登记制度，文件传达到我厂里，厂人武部马上通知到了包括我在内的所有适龄男青年参加兵役征集体检和兵役登记。\n我高高兴兴地去参加了体检，拿到了国防部签发的红色《应征公民证》。\n可是不知道为什么一直没有等到入伍通知，也许是身体条件不允许吧，但是拿到了应征公民证还是很开心的，毕竟是文革后第一次兵役登记，非常有意义。\n这本证我现在还珍藏着。\n最后还是参加了电子管厂民兵组织，成为一名民兵，也是很高兴的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"046_1985年应征证.docx","sourceHash":"b478999e7e513c998a086b3f538bb519f3214a330d707956d8477c0474b2b7f7","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-10 21:49:22"},{"id":"jiang-047","title":"射线管分厂改制","text":"1998年前后，国有企业改制在全国铺开，我们厂也不例外，由于经营困难，不得不将我们这个射线管分厂作为优质资产出让，和北京的一家上市公司成立合资股份制企业。\n由于企业的性质变了，职工的身份也要变为合同制员工，有很多人想不通，不愿意改签劳动合同，我当然也是其中之一。\n新的公司领导不得不亲自出面做思想工作，和职工代表恳谈，拍胸脯保证大家的国企待遇不变，劳动关系不变，并且答应劳动合同由一年一签改为五年一签，签字盖章出安民告示，这才解决了上岗难问题，大家安心上班了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"047_射线管分厂改制.docx","sourceHash":"1a59ca359e69dc7481e9e70a83e996e7f403f9871a3b60eaa4e682b3e61d65f1","chapterNo":6,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-11 07:49:14"},{"id":"jiang-048","title":"同行变对手","text":"合资企业开始在市场经济的大河里游泳了，万事开头难，市场竞争对手多了，实力也不相上下，要和昔日的兄弟姐妹成为对手甚至是仇人，这个压力还真的是很大，很多人拉不下面子，怕得罪同行。\n公司董事会和监事会成员一一下车间，下科室，谈改革，谈转换观念，谈工作方式方法的转换……很快大家都统一了认识，竞争是动力，同行也不是冤家，结仇只是暂时的，只要为国家经济发展做贡献这个大方向都一致，仇人也可以成为朋友。\n销售员，技术员，售后服务专员，这些不得不面对同行兄弟变为竞争对手的同事们，放下思想包袱，愿意走出去做生意了。\n转变观念在当时的改革大潮里面是很正常的，每个人都要接受这个考验，以前的计划经济体制，同行是兄弟，甚至可以互通有无，现在市场经济大家是竞争关系，再正常不过了。转过弯了，事情就好办了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"048_同行变对手.docx","sourceHash":"367079c70187ed5cf369823ff71c371d57e5c99d37e8110323e2fc1e701c3d68","chapterNo":6,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-11 08:05:44"},{"id":"jiang-049","title":"2009年更新家电","text":"2009年，我家先后更新了液晶彩电，换下了显像管电视机；滚筒洗衣机替代了双缸洗衣机；新添置了组合音响；孩子们就近入学了家门口的民办幼儿园。\n我从一线岗位调到了套件库办公室，工作环境有四季空调和一级真空卫生，上班越来越有奔头，工资也慢慢多起来了。\n这一年万象城开张，我们带着孩子进去到处逛，虽然买不起里面的商品，但看看也很开心。\n我妹妹家也显著改善了生活条件，买了轿车，孩子进了家门口的学校读书。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"049_2009年更新家电.docx","sourceHash":"dcaed0ab8a11e63aea3bf102857d907e9b45d0c026e156aaea0bfccef04ba707","chapterNo":3,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-11 08:35:24"},{"id":"jiang-050","title":"2017全家北上","text":"2017年暑假，孩子们小学毕业了，我们全家四口人终于有机会去青岛，威海，大连旅游了。\n那年夏天杭州高温四十多度，马路都晒化了，但高铁一过徐州马上就感到十分的凉爽，到底是北方，又靠海，六个多小时顺利抵达了青岛站。\n青岛，绿树成荫，中西建筑错落有致，蔚蓝的大海边，栈桥上，满是旅游的人群。威海物产丰富，气候宜人，美食和海鲜众多。大连小平岛，渤海湾，海风清新，风景好。\n一周的旅游很快就过去了，坐上东航空客A319直飞上海，探望妹妹一家后回了杭州，孩子们都不想回来了哈哈","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"050_2017全家北上.docx","sourceHash":"a17cda6bc470e1b33e4a69ae5edfd1f3ec0f877a8928a9fc992ec6d7d71a497f","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-11 08:51:11"},{"id":"jiang-051","title":"小学开始放手","text":"从孩子小学时代开始，我们就开始放手管理了。\n幼儿园的时候我是左右不放心，总要牵在手里才踏实。\n上小学以后小芬的一句话点醒了我：“他们总归是要长大的，难道到了十八岁你还要跟在他们后面？”\n的确是有道理，左思右想还是听了她的话，舍得放手了。\n孩子有孩子的天地，父母也不可能包办代替，将来的人生道路，还是要靠自己走的，现在早成长，将来少吃苦。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"051_小学开始放手.docx","sourceHash":"4f5215fb41b210bf7bcb32f461e4ed398df0ab4883801b067e7a209ae9f4f494","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-11 09:54:12"},{"id":"jiang-052","title":"07年国庆吴山广场","text":"孩子小时候最可爱的时候是07年国庆节拿着小国旗去吴山广场玩。\n他俩戴着旅游帽手牵手拿着国旗走在大街上，才三岁的孩子，蹦蹦跳跳，有很多游客给他俩拍照，说双胞胎太可爱了哈哈。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"052_07年国庆吴山广场.docx","sourceHash":"bb1e27b54086c43fa7ed60789567b7f1554f7e84d4552226660c67989a0480ae","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-11 09:58:45"},{"id":"jiang-053","title":"黄老师上课","text":"我是浙江电大杭州分校毕业的，这是个老牌学校，又在市中心附近。作为自学视听生，白天上班晚上上课是常态，学的是汉语言文学专业。\n老师素质好，面授课大家都喜欢听。教历史的黄老师是印尼归侨，人又幽默风趣，一到他上课，教室里满满当当都是人。\n从他那里大家都吸收了不少人生智慧和金句，知识不在多而在于精，他说的一句“读万卷书不如行万里路”，我到现在还铭记于心，黄老师见识多，教会了我们很多人生道理，也爱上了读历史书，懂了以史为鉴的道理。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"053_黄老师上课.docx","sourceHash":"d30d5f68251c3144c1eb036fb310df403b136807d975dd0d81b4fdb6af2dfc6f","chapterNo":2,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-11 10:07:34"},{"id":"jiang-054","title":"电真空工艺","text":"如果重新选择专业，我会选电真空器件工艺专业，一是因为我一辈子都在这个行业做到退休，二是电真空器件工艺员是行业的技术顶尖，我在这个行业实践经验丰富，但理论知识还是不够扎实，如果有下辈子，我一定要报考这个专业，实现工艺员的梦想。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"054_电真空工艺.docx","sourceHash":"81b03031c9e09f651cf33254544cf8cce1caa4cc6b5ae12f708de43e2e14126f","chapterNo":9,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-11 10:14:08"},{"id":"jiang-055","title":"饮马井巷小学","text":"我小学是在杭州饮马井巷小学读的。\n这是个清末就开始建校的老牌重点小学。\n我爸爸，我妹妹也是我的校友。\n学校师资力量雄厚，教学质量很好。\n现在也是市中心有名的一流重点小学。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"055_饮马井巷小学.docx","sourceHash":"115d2c80fe7678274c4ce6749657df8f62cd6ea3378abf98a077124e7e9b8eaf","chapterNo":1,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-11 10:18:54"},{"id":"jiang-056","title":"杭四中杭六中","text":"初中是在杭四中吴山校区读的，走读生，步行来回四十多分钟就到了。\n杭四中是老牌省级重点中学，前身是清末成立的养正书塾，创办人林启是著名的教育家，杭四中也是全国最早的现代中学之一，郁达夫、徐志摩、马寅初等著名知识大家，都是杭四中的校友。\n高中就读于杭六中，走读生，也是清末就诞生的老牌学校，人才辈出，许多中科院杭州籍院士出自于六中。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"056_杭四中杭六中.docx","sourceHash":"c97115ed61a431c138c36e6dab693909ac9dff1bc992e976d9205655815e4ab6","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-11 10:29:07"},{"id":"jiang-057","title":"玻璃烧结入门","text":"学技术，玻璃技术是最难的，没有一两年苦练是成不了才的。\n手工吹制玻璃管，接真空系统，抽真空，没有玻璃烧结技术在身，你根本就不能进电真空器件制造的门。\n这门顶级手艺，师傅只能告诉你一些技巧，但其中的真正烧制诀窍，是要你在不断的失败中总结出来的，没有任何捷径可走。\n你手会烧伤，裤子会被烧融的玻璃烧破，夏天要忍受高温的炙烤，苦是真的苦。\n但是你学会了你就能入门，成为一名好技工，师傅会高看你，领导会重视你，一切都是值得的。\n我就是不怕苦练出来的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"057_玻璃烧结入门.docx","sourceHash":"1bbdfd8929bde97401a1acade47260e74158ed82926b3257b6ee1c626352c66c","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-11 10:39:15"},{"id":"jiang-058","title":"当选团委委员","text":"1987年我由于团干部工作出色，带领三车间团支部创出来了团员青年工作的新局面，紧紧围绕新长征路上青年的先锋突击手作用为增产节约做贡献，被厂团代会选为团代会代表，并光荣的当选厂第七届团委委员。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"058_当选团委委员.docx","sourceHash":"2af83a377da1b438b25ed779745799ea3c4ebaaf464692ef380ed7db1dcb6460","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-11 12:36:24"},{"id":"jiang-059","title":"亚运亚残门票","text":"杭州亚运会和亚残运会开幕，我作为体育迷和摄影爱好者，第一时间买好了票现场观战。\n开幕式前夜足球第一场比赛开打，我和六万多名观众一起入场，亲眼目睹了盛况空前的比赛。\n亚残运会田径赛事更加震撼，残疾人运动员们克服困难奋勇争先的情景，更加激动人心，为他们加油打气的呐喊声响彻云霄。\n这两场比赛的门票我都收藏了起来。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"059_亚运亚残门票.docx","sourceHash":"09b3f12f6487ff52a6fc6a59ce174b376c65abc1afee792d683f1ce14173a079","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-11 12:52:12"},{"id":"jiang-060","title":"泰坦尼克号三刷","text":"《泰坦尼克号》电影1998年4月在杭州隆重上映，这部耗资达一亿多美元的超级好看大电影征服了许多观众，男男女女老老少少从电影院进去后都是红着眼睛出来的。\n我也和朋友一起去看了一场，后来还不过瘾又刷了两场，当时的大银幕胶片版电影画面精美临场感很强，震撼人心。\n那年的街头满街都是《我心永恒》的主题曲，书报亭里面的《泰坦尼克号》画刊被抢购一空，直到现在，这部当时世界上最昂贵的电影也是我收藏品种最全的影碟，经常拿出来放映，回味当年年轻时候的观影感受。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"060_泰坦尼克号三刷.docx","sourceHash":"7d54f2170bd921ee955a8407da440fa3959813e2d36d47d4e1a231f4d8802347","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-11 13:04:35"},{"id":"jiang-061","title":"1976年黑纱","text":"1976年9月9日，伟大的无产阶级革命家，中国人民的伟大领袖毛泽东主席永远的离开了我们。噩耗传来，山河呜咽，天地同悲，神州大地，无不沉浸在悲痛中。\n我当时是上小学四年级，和大人们一起观看了在天安门广场举行的毛主席追悼大会的电视转播，学校礼堂也改成了追悼会分会场，全校师生沉浸在一片悲痛中。\n我们戴着学校发的黑纱，排队向毛主席遗像三鞠躬致哀，泪水直流。主席啊您老人家走了，留下八亿儿女该怎么办啊……这就是当时我们每个人的心声，天，塌了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"061_1976年黑纱.docx","sourceHash":"596090326ac23fc311a7408c34a06560985236d63f052c98eb89ef1232927e7f","chapterNo":6,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-11 13:44:32"},{"id":"jiang-062","title":"四车间做X射线管","text":"杭州电子管厂的X射线管事业是上世纪六十年代接收上海仪表厂的固定阳极X射线管生产线开始起步的，当时成立的四车间成为X射线管产品的设计试制基地，集中了优秀的科研人员，为实现中国自主拥有医疗诊断用射线管的目标而奋斗。\n经过三十多年的不懈努力，到上世纪八十年代末九十年代初形成了非常完备的产品体系，实现了固定阳极、工业探伤、旋转阳极三条完善生产线，可以完全自主生产各种用途的X射线管。\n我1994年去了四车间工作，终于实现了做X射线管产品的心愿，也是非常荣幸和高兴的。当时已经有两百多员工，多位高级工程师领衔，陈晓鸣、童桂福、王德进。\n1998年和北京合资后，实力进一步增强，成为了国内中低端产品最大的龙头企业。\n\n\n这也是我企业生涯里面最欣慰的事情，很高兴能够亲身经历市场机制改革，成为股份制企业的员工。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"062_四车间做X射线管.docx","sourceHash":"edf39ad85d6d5ce336099d4515be76a523a56651b9a5c70a39b99a8161df2ff8","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-11 15:00:20"},{"id":"jiang-063","title":"三家老影院","text":"上世纪七十年代到八九十年代，是传统电影院的全盛时期，那时候新华电影院、西湖电影院、太平洋电影院，在市中心西湖边上三足鼎立，十分红火。\n有好片子上映的时候，买票甚至是要熬夜排队，印象中好像有《瓦尔特保卫萨拉热窝》、《桥》、《追捕》、《望乡》等好看的外国电影，都是一票难求。\n记得我爸妈那时候由于没有买足影票，都买两张儿童票让我和妹妹压低身体高度骗过检票员进场的（当时规定1.5米以下儿童可以买儿童票）。\n这三家电影院都给我留下了美好的回忆，不知道在它们那里看过了多少部电影，直到新式的立体声多声道小厅影院流行起来才正式退出江湖。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"063_三家老影院.docx","sourceHash":"3747ae4d3e4dc11f84244fe0ca215cb4f4fba7545502932cce7a8196171f3310","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"CHILDHOOD","recordedAt":"2026-08-11 18:34:31"},{"id":"jiang-064","title":"妈妈织毛衣","text":"我的妈妈是四零后，上海人，也是当年全厂职工心目中的美女，气质很好，心灵手巧。\n童年时代我和我妹妹的毛衣，都是她手工编织的，爸爸的也是，“温暖牌”毛衣都是她参照当年的上海时装杂志《上海画报》精心手织的，穿在身上既精致时尚又暖暖的。\n妈妈和我一样也是三车间出身，妈妈的两个小姐妹陶美云阿姨和杨树英阿姨后来成了我的师傅和同事，我们一家三口三职工的故事，也在厂里传为佳话。\n妈妈过世已经二十多年了，孙子孙女现在也已经长大成人了，愿妈妈在天堂安好，我们永远爱你！（图中前排左起第四位就是我妈妈）","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"064_妈妈织毛衣.docx","sourceHash":"80210fc88d4500d80a3db75048f7744645577bc8afb93ccd455f835e30014b94","photos":[{"id":"jiang-photo-064","url":"v17/assets/jiang-teacher/064-image3.jpg","name":"母亲故事卡所附老厂合影，人物位置按原文待本人核对","caseReference":true}],"chapterNo":5,"stageId":1,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-11 19:00:39"},{"id":"jiang-065","title":"新华电影院","text":"1977年拨乱反正开始以后，文革前十七年摄制的电影和国内外文学作品相继解禁，人民群众如久旱逢甘霖一般抢购电影票和优秀的国内外文学名著。\n杭州新华书店门口，各大电影院门口大排长龙。\n当年的解禁电影记得有《洪湖赤卫队》《烈火中永生》《槐树庄》《大浪淘沙》《青春之歌》《年轻的一代》《红日》《梁山伯与祝英台》《红楼梦》……\n世界文学名著有《巴黎圣母院》《悲惨世界》《三个火枪手》《基督山伯爵》《红与黑》，国外影片有《百万英镑》《被侮辱与被迫害的人》《罗马十一点》……\n我也是这些阅读和观看大军的一员，在新华电影院天天看电影，书是隔壁大哥哥买回家后借来看。\n“四人帮”时期的反动文化专制主义，把优秀的文艺作品一律打成“毒草”，毒害不浅！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"065_新华电影院.docx","sourceHash":"ef2aa03fef3e90fdbbd65931593728540dc1e57edce03ff535bd95bf50f8e350","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-11 19:30:34"},{"id":"jiang-066","title":"八十八师纪念碑","text":"我爸爸是1937年出生的，经历过战乱困苦的年代，抗战时期杭州曾被日寇侵占，我家曾有三位亲人死于日寇之手，国仇家恨，一代代的传下来了。\n闲暇时他偶尔会和我们聊天的时候讲起杭州沦陷的往事，他说那个时候，杭州市民路上看见日军和汉奸，都要脱帽鞠躬的，你不鞠躬就要挨毒打，学校学生必须学日语，日语老师都是日军军官……\n国弱被人欺，这种奇耻大辱深深地植根于少年时代的他，他一直嘱咐我们不要忘记杭州曾经遭受的蹂躏和苦难，吾辈当自强。\n这些杭州的苦难岁月，也在我们后辈心中难以忘却，所以我每次去西湖一公园摄影，都要到国民革命军八十八师抗战纪念碑前看一看，向抗战英烈致以崇高的敬意，也把他们的英姿摄入镜头，以留给后人瞻仰。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"066_八十八师纪念碑.docx","sourceHash":"cddac2542b111c65be7e75b96f3b4c5bb822919a117f634e78c77b1989b687df","chapterNo":5,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-11 20:24:38"},{"id":"jiang-067","title":"小芬穿西服","text":"当时是小芬的笑容打动了我，她穿一身西服套装，自然而又大方的仪态，让我顿生好感，她和我妈聊天的时候，我就觉得就是她了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"067_小芬穿西服.docx","sourceHash":"d5a0dbf061ecf4f806262e67fc7acfefebf22c5d3a05578787bddb1f920f066e","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-11 20:56:33"},{"id":"jiang-068","title":"手牵手逛夜市","text":"我和小芬恋爱期间最甜蜜的事就是逛夜市，那时候庆春东路的夜市很热闹，两个人手牵手一起逛，买个手机壳，买副耳机，买件衣服，都是我们特别开心的时候。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"068_手牵手逛夜市.docx","sourceHash":"b2e75f1424c58375ca34943179b337390a256be2c3bb4128e0e1c65183e5dea1","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-11 21:00:18"},{"id":"jiang-069","title":"江干区登记","text":"也没什么求婚，两个人结婚的钱攒够了，就跑去江干区婚姻登记处登记了，哈哈就是这样简单。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"069_江干区登记.docx","sourceHash":"a2fb277f884aef9ef5ee66bd21eb2abcd25f5d482d0546b0c85dcd99d5dc4285","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-11 21:03:55"},{"id":"jiang-070","title":"新婚初期生活","text":"那时候的生活很简单，就是分别上班，下班回家了做个饭，吃完了看看电视或者去超市，夜市逛逛，偶尔出去看场电影，就是很舒服的享受了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"070_新婚初期生活.docx","sourceHash":"bf91cbc27d149893135f76cf388d404decf46a80a8760ed3df01c14c3ab01b73","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-11 21:07:01"},{"id":"jiang-071","title":"补个求婚","text":"如果能回到我们刚恋爱的时候，那当然是补个求婚仪式，补上一束鲜花了。可惜她已经不在了，我永远都怀念她。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"071_补个求婚.docx","sourceHash":"353429e1c1c255d4147cbc9421d338d47b797b405078e9ee5f8e7fabeb5fc45a","chapterNo":4,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-11 21:08:34"},{"id":"jiang-072","title":"八十年代书报亭","text":"我喜欢看书，从小学时代开始，大概已经看过了上万本书。\n小时候看《十万个为什么》，萌生了热爱科学的种子；中学时代遍读世界名著、毛选、世界历史；大学时代读各种各样的杂书。\n八十年代杂志遍地开花，《环球》《世界之窗》《海外文摘》《读者》《文化与生活》《航空知识》《世界知识画报》成了我们八十年代青年了解世界的窗口。\n当年的书报亭遍地都是，买书非常方便，有限的收入买书成了最大的消费，但钱花得一点都不肉疼，因为知识在你肚子里了，人家都带不走。\n当年同事们攀比不是比房子汽车，而是谁读的书多；厂里举办的智力竞赛我过关斩将得了第三，同事们都折服我书读得多。\n那个时候崇尚知识就是力量，社会尊重知识尊重人才。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"072_八十年代书报亭.docx","sourceHash":"c175dd87b5a256a9c6e36ce4b2f2df8647ec40016f03a01e0fa369be725eea18","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-12 09:02:16"},{"id":"jiang-073","title":"老虎苍蝇一起打","text":"最让人担忧的是一切向钱看的社会价值观和官员贪污腐化屡禁不止问题，一切向钱看，不符合社会主义核心价值观和国家的性质，官员贪腐严重损害党和国家的利益，败坏社会风气，严重损害党和政府的威信和信誉，关系到国家前途和人心向背。\n好在十八大以来严打各种各样的贪腐蛀虫，老虎苍蝇一起打，让我们看到了实实在在的成果，干部作风转变了，队伍纯洁性大大提高，人民有信心多了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"073_老虎苍蝇一起打.docx","sourceHash":"cf7633a65a5158114c27f5a807edb4b30775db1de60a0ec3c6e704abd38aaae8","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-12 09:52:55"},{"id":"jiang-074","title":"D80胶片感","text":"要说才艺，普通话和摄影算吧。\n我上小学的时候因为看电影电视多，学会了一口标准普通话，1984年参加了浙江省人民广播电台举办的普通话大赛，得了鼓励奖，认识了一起参赛的刘忠虎崔健等普通话爱好者，她俩后来进了杭州电视台。\n摄影是工作以后才开始学的，先是胶片傻瓜相机拍，后来慢慢过渡到胶片单反，最后进入数码单反阵营。要说哪一台相机最出彩，可能还是尼康D80数码单反相机吧，它画质色彩特别有特色，胶片感特别好。\n现在考出来了欧洲开放大学国家地理摄影师认证，据说这张证书是摄影职业天花板，也算是一种成就感吧，哈哈！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"074_D80胶片感.docx","sourceHash":"1bae4112e51588b68e3421c868711c4bf05ff228509704416ef3f63596b64aab","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-12 10:05:42"},{"id":"jiang-075","title":"引进西门子技术","text":"中国的现代化建设，实际上是从1972年开始的，由于中美关系缓和，带动了一大批西方国家和新中国建交，因此毛主席作出决策，以上海金山石油化工总厂项目为契机，向西方国家引进一批现代化成套设备和技术，于是相继和西欧日本谈判购入了金山石化、宝钢、鞍钢\n等项目的技术，改革开放后又使用港澳资金建设了经济特区。\n我们的工厂也迅速和西德西门子公司谈判引进了急需的高速旋转阳极X射线管技术，和日本帝国公司谈判引进了黑白显像管项目，极大的提高了企业的技术能力和竞争优势，听说当时杭州汽轮机厂也和西门子合作引进了先进的三系列工业汽轮机项目。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"075_引进西门子技术.docx","sourceHash":"01129d410e1a12b7b749d40690722427daa29704d25285d1273d179450728ec3","chapterNo":3,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-12 14:53:14"},{"id":"jiang-076","title":"1987年搬新居","text":"1986年中东河改造开始，我家整条弄堂也被征迁，经过协商，统一安排到新建的采荷新村安置，我家分到了两套一中一小房子。\n能够住进有独立卫生间，宽敞亮堂的新建住宅，真的是很开心。\n经过简单的装修，1987年春节前正式搬进了新居，我和妹妹都有了独立的房间，真的是太好了！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"076_1987年搬新居.docx","sourceHash":"ff731c46a02757f181aead59c12c7a978bc872f0b6c19fc34090d91293bf1bca","chapterNo":5,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-12 17:58:43"},{"id":"jiang-077","title":"提前退休","text":"2019年秋，由于企业所在地被征迁，新厂房远在下沙，交通不便，又恰好我身体不好，符合提前退休条件，于是经过和领导协商办理了提前退休手续。\n整理好了办公室的东西，和同事办好了交接，依依不舍的在石桥路10号的厂区走了一遍，拍了整个公司厂区和办公楼的照片，才和相伴到老的同事们话别，告别了三十九年的职业生涯。\n电真空这个职业干了一辈子。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"077_提前退休.docx","sourceHash":"4506c1405bd9a328c09bec5e137efcc8aa5e92eff766461fa9a77ac16b2ac72a","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-12 18:11:16"},{"id":"jiang-078","title":"2003年春节外滩","text":"2003年春节期间，我们全家到上海团聚。妹妹一家人我们一家人在上海过春节，我们还去了外滩观光，外滩的夜景很美，东方明珠塔特别漂亮。\n没想到回了杭州后不久，一场非典型肺炎疫情正在悄悄地袭来。\n起初是传说中的广东神秘肺炎，后来全国各地都出现了病例，一时间口罩板蓝根冲剂脱销，企事业单位都发放了预防药品，由于中央行动有力，到六月初疫情终于退去，阳光明媚的盛夏大家终于可以不戴口罩正常生活了。\n事后回想起来还是有点吓人的，当时在外滩我们都没有戴口罩，没有中招也着实是幸运。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"078_2003年春节外滩.docx","sourceHash":"91dc2f4d3b01456642a747f10f6616bf73e85f9821e64315012fed06de77ff83","chapterNo":5,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-12 20:05:15"},{"id":"jiang-079","title":"新华电影院三刷","text":"1975年春节前后，在党中央的亲切关怀下，广大电影工作者克服极左路线的干扰破坏，深入生活创作了一批优秀的故事片并摄制完成，《创业》、《海霞》、《难忘的战斗》等影片陆续和观众见面了，受到了被八个样板戏搞得片荒而苦苦等待好片子的广大人民群众热烈\n欢迎。\n但是“四人帮”又开始发难，诬陷这些影片为邓小平翻案，一时间又搞得人心惶惶，大家好不容易有好的影片看，这下又要黄了，广大观众不服纷纷提出来质疑和不同观点。\n后来毛主席听说了此事，立即要求文化部送影片到中南海放映，毛主席看过这些影片后批示“不要求全责备，可以发行”，“四人帮”的阴谋破产。\n我在新华电影院看了影片以后非常满意，同学们也都说这些电影都很好看，特别是《海霞》和《难忘的战斗》，不落俗套，不搞三突出和高大全，英雄人物也很有个性特点，不刷三遍不过瘾，连着几天看《海霞》，里面的主题歌《渔家姑娘在海边》特别好听，画面也很美，\n由于是主角原型取自于浙江温岭洞头县女子民兵连，特别亲切感，到现在来看这些影片还是很有魅力的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"079_新华电影院三刷.docx","sourceHash":"f2d8d34eb7df6725b81442fc77185afa066450e71ecc73a66d0fd9c903fa4442","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-12 22:54:05"},{"id":"jiang-080","title":"常备布洛芬","text":"没想到2020年初一场新冠肺炎疫情袭来，由于我有非典的经验，在得知武汉发生的疫情消息后我马上就让家人第一时间戴上了口罩，让孩子们外出上学的时候注意防护。\n在党中央国务院迅速采取抗疫部署后，一场伟大的抗疫全民战争打响，当时的严防死守下，人民的安全感是非常好的，我们积极配合，全家人非必要不外出，不扎堆，做好自律，遵守小区封闭式管理规定，安全的度过了防疫期。\n当时我们公司也积极行动起来为全国抗疫一线提供X射线管产品，我虽然退休了还是和同事们保持联系，为他们加油鼓劲。\n放开以后，我们全家平稳度过了感染高峰，幸亏常备了布洛芬。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"080_常备布洛芬.docx","sourceHash":"0dfb60b09b6544a8e54b075706830515a9d601453c640b3cede4a5bc147776ae","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-13 09:38:41"},{"id":"jiang-081","title":"1976防震棚","text":"1976年是非常不平凡的一年，这一年吉林陨石雨，唐山大地震，周总理、朱德委员长、毛主席相继离世，山河呜咽，大地同悲，十里长街送总理，这些悲伤的画面至今还留存在脑海……\n九月份江苏溧阳又发生地震，杭州有震感，当天居委会就组织大家住进了防震棚，真的是非常难忘的经历。\n防震棚是用钢管搭建的。\n当时大家都在想：毛主席走了，党和国家向何处去？有没有人站出来带领我们继续前进？\n十月份终于一声春雷来了：华国锋叶剑英领导中共中央决定对“四人帮”进行隔离审查，华国锋同志当选中共中央主席、中央军委主席，天，终于亮了！\n刊载华主席穿军装登上天安门城楼向欢呼雀跃的人民群众亲切挥手照片的报纸传遍全国，祖国的春天来了，英明的领袖来了！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"081_1976防震棚.docx","sourceHash":"42f4c35a056f868754b2bac58536a448e9d2faead522a985f59a5dcaea58270f","chapterNo":6,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-13 09:59:27"},{"id":"jiang-082","title":"阅报栏春光","text":"1978年小平同志复出主持中央工作，当时我刚刚考进南山中学初中部，作为少先队员和语文课代表，班主任潘老师要我多读报纸，带头关心国家大事。\n于是我每天下午放学以后都去国货路那边的杭州日报社阅报栏看报纸。\n关于检验真理的唯一标准大讨论，知青返城，落实老干部和知识分子政策，为刘少奇、贺龙、彭德怀等老同志平反，恢复高考……一系列拨乱反正的决策在贯彻落实，最重大的新闻是十一届三中全会召开，全会号召把党的中心工作转变到经济建设上来，改革开放的国策正式\n开始落实了！\n这张报纸的内容，至今在我记忆中回响……春天真的来了，四化建设的春天来了！也就是在那一天起，要好好读书掌握文化知识的念头便开始扎根，读书的积极性自觉性强了，知道不能再和以前“文革”一样荒废学习了……","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"082_阅报栏春光.docx","sourceHash":"46db8c74330cce2a376919df21de8113e5a7660d522508876fad822ed5aa282c","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-13 10:22:23"},{"id":"jiang-083","title":"老厂人重聚","text":"2024年和2025年秋，我们原杭州电子管厂退休职工在群主魏咏之师傅和组委会组织下进行了第二、第三次活动。\n感谢老魏和同志们的信任，推举我加入组委会，负责现场音响调控和视频播放工作。\n我认真准备了素材和视频、音乐，提前到现场准备好所有的流程。\n老厂长夏和章、老书记许松涛，都已经九十四岁高龄，但身体硬朗，他们一一和大家握手，互致问候。\n相聚一堂，分外开心。企业虽然没有了，但大家的情意永在！愿兄弟姐妹们晚年幸福安康，年年都见！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"083_老厂人重聚.docx","sourceHash":"c33862aa0ff4d90d26e9b64c1fd6547c2de3b87f822605576026aaf5cbc238b1","chapterNo":7,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-13 11:13:02"},{"id":"jiang-084","title":"托爸妈找临时工","text":"刚刚高中毕业的时候，托爸妈给我找临时工做是我做过的最对的一件事。\n如果我在家待着，恐怕会成为四体不勤五谷不分的啃老族，当时杭州土话叫“荡长”（家里荡荡的意思），也有可能会学坏，跟着黑道大哥当小弟去了。\n后来开小学同学会得知有好几个在家当“荡长”的同学被严打抓进去了，罪恶最大的两个同学被判到青海省劳改十年。\n在做临时工的几个月里，我认识了劳模师傅，学会了站柜台，掌握了糖果一抓准的技艺，学会了标牌油漆工手艺，这都是我宝贵的精神财富，没有走上邪路，这比啥都强，如果是劳改十年，人生等于报废，这就是选择对还是不对可以决定你的人生的大问题。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"084_托爸妈找临时工.docx","sourceHash":"ab0a64cea354e0ad7a5d5bd0dc867ae8d89bc4e1e29cd19214aac3b55d37f2cc","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-13 14:16:38"},{"id":"jiang-085","title":"小学荒废三年","text":"如果人生可以重来一次，我会更早开始好好学习，而不是被“文化大革命”荒废了小学一到三年级的宝贵时光。\n如果是这样的话，我会顺理成章的考上大学，和我妹妹一样成为全日制本科生。她考上了武汉中南民族大学民族学系，那我起码也会考上一所好的本科学校，人生道路会比现在更幸福，可惜没有重来的机会了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"085_小学荒废三年.docx","sourceHash":"9f7a9867d7d032ba493c308e018ce3ee7b56f33793ddff8809b68c97d0d24394","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-13 14:21:08"},{"id":"jiang-086","title":"六十年代同事","text":"我父母是上世纪六十年代在一起工作的时候相识相知相爱的。\n我爸是五十年代老高中生，我妈因为抗战时期战乱只读到初中就辍学了，所以她特别喜欢我爸这个文化人。\n我妈上海人，一贯的细腻温柔，又很精致讲究，从小就把我们两个孩子打扮得漂漂亮亮清清爽爽的。六十年代很贫困，但我妈精心操持家务，我和我妹妹走出去一点也不像别人家的孩子一样邋邋遢遢，我妹妹就像个漂亮的瓷娃娃一样人见人爱。\n我爸读书好的特质也遗传给了我们。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"086_六十年代同事.docx","sourceHash":"c882fc8a83ff6ac8cc3c42f4f4cbecc289b029f9c696a1d4a324072a8c6a4f06","chapterNo":5,"stageId":1,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-13 14:32:18"},{"id":"jiang-087","title":"喜得龙凤胎","text":"我们结婚一年后才准备要孩子，刚开始的时候没什么动静，我妈急了，催着我们赶紧去医院检查会不会有什么问题，结果一切正常，医生说是我们过分紧张了，越是想要就越怀不上，鼓励我们尽量放松心情。\n后来果然如医生所说孩子来了，还是双胞胎，医生说要好好休息保胎，争取顺产。我们两个是最听医生话的人，就老老实实的静养保胎。\n到九个月的时候，陪小芬去童装市场买童装回来就开始阵痛了，我马上打车送她到省妇保产房，晚上就喜得龙凤胎姐弟，母子平安还是顺产。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"087_喜得龙凤胎.docx","sourceHash":"5db73925b8863a09fe9e7c6f72b187ce09ed7d0770aa67a51270a3e11f5d692f","chapterNo":5,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-13 14:42:05"},{"id":"jiang-088","title":"不拍桌子","text":"在教育孩子上，我和伴侣没有什么分歧。我们的共识就是要让孩子健康快乐地成长，决不把我们的观点强加给孩子，也不逼他们学各种各样的才艺，读各种五花八门的培训班，顺其自然。如果过早地干预他们的学习和成长，很可能会适得其反。\n我们从来没有打骂逼迫孩子做作业，拍桌子都没有过。现在听说有的家长因为辅导作业被气成脑溢血或者打孩子打成脑震荡，我都感到非常匪夷所思，很惊讶，干嘛要把自己和孩子搞成这样啊？宽松自由的氛围不好吗？","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"088_不拍桌子.docx","sourceHash":"d8a334a321b60e20f90a7d4d2f40d26c5989f4ecf816ac0a3d67055b9fadb819","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-13 14:50:27"},{"id":"jiang-089","title":"拍一辈子西湖","text":"作为老杭州人，我自然而然就有一个西湖情结，从小就热爱西湖，现在退休了也选择住在市区的老房子里，图的就是一个离西湖边上近，可以随时过去走走看看。\n天下西湖三十六，最美西湖数杭垣，“上有天堂，下有苏杭”不是白叫的，西湖的山水，西湖的秀美，是任何地方都比不上的，我的摄影作品也一直都是西湖主题，我打算拍一辈子西湖，它的美是一年四季的美，千年的美，无可比拟的美……\n西湖情结，也要世世代代的杭州人传下去，保护好西湖，是杭州人的责任。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"089_拍一辈子西湖.docx","sourceHash":"5038fb454104f04a9a5855df8352aee7da7b6f955f3ccca4b5e0dec02d74ad52","photos":[{"id":"jiang-photo-089","url":"v17/assets/jiang-teacher/089-image3.jpg","name":"拍一辈子西湖故事卡所附湖景","caseReference":true}],"chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-13 15:25:18"},{"id":"jiang-090","title":"公有制到多种所有制","text":"最大的社会变迁是从完全的公有制过渡到多种所有制。\n我认为这个变化是好事，以公有制为主体多种所有制共同发展，可以促进经济繁荣，实现社会主义市场经济健康发展。\n我们没有沿袭苏联那套僵化的计划经济体制，而是坚定不移的探索出一条符合中国国情的发展道路，这是邓公和他的后人为我们留下来的最宝贵经验。\n市场经济体制不是资本主义特有，社会主义国家也可以搞，这是非常了不起的理论突破，解放思想，实践也证明了是成功的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"090_公有制到多种所有制.docx","sourceHash":"5d6e6070dea72a3b930472da67fe2c50188c655f6e27306b3de530462436040f","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 15:56:29"},{"id":"jiang-091","title":"亚运建厂庆典","text":"印象深刻的有建厂五十周年庆典恰逢北京亚运会开幕，杭州电子管厂党委在杭州东坡剧院隆重举行建厂五十周年庆典。\n为了配合迎亚运的气氛，厂团委组织我们团员青年大合唱《歌唱祖国》和《亚洲雄风》，非常的震撼人心。\n我也参加了大合唱。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"091_亚运建厂庆典.docx","sourceHash":"b10149a1326276497310035a3f36860bf04008687d86b52b66ba8d250e189543","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-13 16:07:00"},{"id":"jiang-092","title":"李铁映来厂视察","text":"八十年代，国务委员、时任电子工业部部长李铁映同志来我厂视察。\n那天李部长在厂长、书记和随行人员的陪同下来到我们三车间视察。\n李老穿一件白色短袖衬衫，戴眼镜，非常温文尔雅风度翩翩。\n他详细询问了我们的军品电子管生产情况，亲切地和我们每个职工握手，勉励大家要为国家的国防现代化事业做贡献，加快速度满足部队装备需要，嘱咐我们青年职工要多学习文化知识，提高自己的业务水平。\n四十多年过去了，李老的音容笑貌仿佛还在眼前，李老走了，但他留下的老一辈革命家风范始终铭记于心，他勉励我的话我还在和自己的子女讲，要一代代传下去。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"092_李铁映来厂视察.docx","sourceHash":"2dc7fdb9dd50cb103f19e6816ca6328c0a0cab8029cad5812eeececbc4204e64","chapterNo":3,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-13 16:20:36"},{"id":"jiang-093","title":"生老病死自然","text":"生老病死，都是自然规律，有生必有死，但只要活得有价值，死也没有那么可怕了。\n在世一天就要开开心心每一天。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"093_生老病死自然.docx","sourceHash":"67c2bc7b5525dd7137687c237984a5bcd18d5e678df62616b793e5abe0cbb101","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 16:25:51"},{"id":"jiang-094","title":"变老的好处","text":"变老了，人生经验更丰富了，可以回味和思索自己的一生，不是一件好事么？\n但心理要保持年轻，不能浑浑噩噩，要跟上时代潮流，就好了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"094_变老的好处.docx","sourceHash":"b6a8b8f935462671d7d5131c0fe34f36c03eebf6fb5321353371e55ae495982b","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 16:29:35"},{"id":"jiang-095","title":"翁森鹤搞武斗","text":"年轻时候不理解“文化大革命”，现在慢慢理解了，领导人的出发点是好的，但被某些别有用心的坏人所利用，造成了空前的浩劫，这是我们要记取的教训。\n例如我们浙江省的造反派头头翁森鹤，搞打砸抢，搞武斗，就是别有用心的坏人。那个时候翁森鹤自封“造反派司令”，带着藤帽铁棍到处打砸抢，干了不少坏事，粉碎“四人帮”后才被判刑查办。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"095_翁森鹤搞武斗.docx","sourceHash":"d5e2f98ec322361d4df1582a88dab4f05ee0446d93b3d2c51e419ae2b0c7a656","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 16:32:56"},{"id":"jiang-096","title":"愿试数字纪念","text":"这当然是很好了，可以尝试一下，哈哈！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"096_愿试数字纪念.docx","sourceHash":"d77625e4d83a2ca8f5a063aea5d1d13bd678e38dce19608c111231cb72d1db41","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 16:41:27"},{"id":"jiang-097","title":"绿色生态葬","text":"不搞铺张浪费，大操大办，毫无意义，只要后人从简就好。\n绿色生态葬是我和家人商量为孩子她妈准备的，已经入葬了，将来我也是。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"097_绿色生态葬.docx","sourceHash":"6a70deffb01d03679f25f9de296996498f0fa08f6204b61403c97060ee096bc2","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 16:45:37"},{"id":"jiang-098","title":"雨天听雨","text":"我最喜欢的声音是早晨的鸟鸣和下雨天的雨声，大自然的气息扑面而来。\n雨天泡一杯茶坐在客厅听雨，心情自然而然的宁静，非常的安逸。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"098_雨天听雨.docx","sourceHash":"2537db18fa339fd3fe1b38b3fc5e4ec0c20c82629515284da70389d97373a814","chapterNo":10,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 17:49:07"},{"id":"jiang-099","title":"nightly film","text":"听音乐和看电影是我最享受的放松方式。\n现在是使用蓝牙功能手机点播网盘里的音乐，特别方便。\n看电影有两种方式，客厅投影和卧室电视，随意播放蓝光影碟和网盘电影。\n光影世界，任我穿越……各种世界名片，尽情的欣赏。\n每天晚上一部电影，乐在其中！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"099_nightly film.docx","sourceHash":"56fd1cc5c68a4d6b66956e0e9b74c363c6658eba65fb450b918c467bd847168f","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 17:56:30"},{"id":"jiang-100","title":"两面人最看不惯","text":"两面人我最看不惯，领导面前一套，同事面前一套，当面一套，背后一套的人，就是小人。\n就像有些贪官，骑破自行车上班，穿破破烂烂的衣服，伪装廉洁，背后却是花天酒地纸醉金迷的生活，太讽刺了，这种拙劣的表演最终还是骗不了人的，该进班房还得进，因为会露馅的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"100_两面人最看不惯.docx","sourceHash":"d7f278029d29a0f132e824d501c75eaea241f76ed79e281d9f0a04b93f6e4991","chapterNo":8,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 18:54:48"},{"id":"jiang-101","title":"毛爷爷走了","text":"哭得稀里哗啦的是毛主席追悼会的时候，因为我们从小就热爱毛主席，崇敬毛主席，毛主席就是我们心中的太阳，他就像慈祥的爷爷一样。\n现在突然失去了这么亲的爷爷，再也看不到爷爷了，在孩子们的心中是非常的悲伤，爷爷走了，这个家怎么办呢？越想越悲伤，无忧无虑的孩子们都哭得撕心裂肺。\n也就是在那天起我突然发现了死亡是这么的可怕，会把爱护祖国花朵的爷爷也带走了……我们小孩子朴素的感情就是这样子。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"101_毛爷爷走了.docx","sourceHash":"5fc772c4546a855344797565a53ddb08bcb45c8bd9bae4ea76c319a1799c6f21","chapterNo":1,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"CHILDHOOD","recordedAt":"2026-08-13 19:14:29"},{"id":"jiang-102","title":"朋友不在多","text":"人生难得一知己，有心灵和情感共鸣，就可以无话不谈的朋友，是人生最大的乐趣。\n朋友不在多而在于精，要有真心朋友而不是酒肉朋友。\n我的朋友中有同龄人也有忘年交，我觉得很有意思，多交朋友会开阔眼界，会让人生变得更加美好。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"102_朋友不在多.docx","sourceHash":"f97f025830f39f73129d5162fe14ce5aec904883a3de90ba38ed842f48305cdd","chapterNo":7,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-13 19:21:29"},{"id":"jiang-103","title":"FU5还在发光","text":"我在电真空这个行业工作了一辈子，在上世纪电子管还是黄金时代，各行各业都要用到它，我们的产品囊括工业农业国防医疗等各种各样的用途。\n经过我手上生产出来的电子管，在这三十九年中大概已经有几百万只吧，它们有的至今还在发光发热，比如FU5发射管，在发烧音响上被大量使用。我们的品牌是“杭州”，特别骄傲和自豪。\n\n为国防现代化生产陶瓷放电管，都是通宵作业。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"103_FU5还在发光.docx","sourceHash":"c8160118d93ad259d88500477feabeab9af46e9f4a317e2596fcd8061aefaf01","photos":[{"id":"jiang-photo-103","url":"v17/assets/jiang-teacher/103-image3.jpg","name":"故事卡所附杭州牌电子管产品图，非特定型号鉴定","caseReference":true}],"chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-14 08:02:11"},{"id":"jiang-104","title":"想通了乱象","text":"六零后都是生在新中国长在红旗下的，自然也是爱国爱党坚信社会主义核心价值观，毛主席时代的教育就是要做老实人办老实事，我想我也是做到了。\n至于说现在贪官抓不完，诈骗犯遍地走的乱象，我也是想通了，因为在市场经济体制的情况下必然会有这种情况，社会不是真空，怎么可能要求绝对纯洁无瑕呢！\n发达国家的这种现象比我们更严重，只有以法律的手段来解决问题，铲除腐败的土壤，限制官员的权力，加强舆论监督，这些现象才能得到遏制。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"104_想通了乱象.docx","sourceHash":"a7de3cd9e91f8d8e9247ea9acb443cd2df2e8f844015666f032490c596bff518","chapterNo":8,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-14 08:31:54"},{"id":"jiang-105","title":"三十九年工作","text":"夜深人静的时候我经常想的是这一辈子都是在工作中度过了三十九年，陪家人的时间很少，连我老婆产检我也只陪她去过一次，我妈妈住院也只去过没几次。\n现在就是陪孩子和老爸多一些了，算是补偿吧。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"105_三十九年工作.docx","sourceHash":"912d1ee2a1451a57d43d3d2fca4fef5974e3060da63b73a371a735e7ef813e98","chapterNo":9,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-14 10:25:05"},{"id":"jiang-106","title":"儿子缝六针","text":"儿子被同学无意中撞伤，缝了六针。\n还好我及时请假带他去了医院，没有大碍。\n孩子在学校的意外还有很多，都是在惊吓中慢慢长大的，也是正常现象。\n怕是怕的，养这么大万一有个三长两短怎么办？也不是没担心过这个问题，所以意外险是一定要买的，至少有保险公司为你兜底，放心一些。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"106_儿子缝六针.docx","sourceHash":"0fa6b2bf859b695cbc0bc1b0d85de924932e19ce9ca494fec0261d5fb5d7dde8","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-14 10:31:17"},{"id":"jiang-107","title":"新婚游船行","text":"最幸福的时光就是一起去苏州无锡新婚旅行，坐着“天堂”号游船沿大运河第二天早上直达苏州，跟着旅行团漫游苏州、无锡。\n还认识了一对江西南昌小夫妻，男的是电工，女的是护士，成为了好朋友。回了杭州还和他们有通信来往，大家都很投缘，感到新婚无限美好，对未来充满期待。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"107_新婚游船行.docx","sourceHash":"a5f246ec31b82684dce298121fe2eea506affbfcb8a619fea30acfdaad657bed","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-14 14:51:16"},{"id":"jiang-108","title":"育儿后平衡","text":"最考验我们的就是有了孩子以后怎么安排好工作、生活、学习、职业提升、家庭收入分配、友情与亲情等各方面的平衡。\n不能说没有争执，分歧是难免的，但只要双方互谅互让，总能够找到一个平衡点。\n我们也是在学习中不断进步，实现共赢。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"108_育儿后平衡.docx","sourceHash":"dd84686a1576dcdae26df4545e8d4188f9395ba5253384131baf2f14e74a9303","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-14 14:57:26"},{"id":"jiang-109","title":"九分婚姻","text":"打九分吧，不能说百分百完美，因为人都是不完美的，总有磕磕绊绊在所难免。\n但总的来说还是我让着她多一些，毕竟我们年龄相差十岁，年长者总要让对方一些，也是人之常情。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"109_九分婚姻.docx","sourceHash":"d0b129ae7913315a8c0bedc6e0de77ae89a062f1882b2f4a06a783213d605945","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-14 15:01:27"},{"id":"jiang-110","title":"她操心更多","text":"应该还是我多依赖她一些吧，她的家务活比我能干一点，我的衣着搭配，孩子的衣服，家庭用品的添置，都是她操心多一些，孩子的学习我多操心一些，也就是各有所长吧，各自好好为这个家庭付出，就是很幸福了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"110_她操心更多.docx","sourceHash":"f93aea95f438bec1181a9211bad3833d2f70426e3d3457b6ea7812e1bc3fea36","chapterNo":4,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-14 15:06:57"},{"id":"jiang-111","title":"吵架不过夜","text":"我们的默契是吵架不过夜，不翻旧账，不恶语中伤对方，哪怕再发火也不摔东西，有事好好商量，不把自己的想法强加于人。\n我太太喜欢看电视剧，我也陪着她看，从来不会怕烦。她喜欢逛超市，我也陪着她逛。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"111_吵架不过夜.docx","sourceHash":"71812c26f4799de8e352107aeab01fa012c61e22c2a0f62721419f9d2203622b","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-14 15:13:38"},{"id":"jiang-112","title":"千万下岗","text":"千万国企职工大下岗，是应该被记住的，这是血泪史，广大下岗职工为国家经济结构调整作出了重大贡献，他们应该被记住。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"112_千万下岗.docx","sourceHash":"f34317ad845e44653be8d9285dd8487299a6691d8d6ee681c4445b8398eecb55","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-14 15:26:09"},{"id":"jiang-113","title":"邻居大哥去黑龙江","text":"幸福各有各的定义，我认为我还是幸福的，没有经历过上山下乡运动，比起五零后要好很多。\n比如我的邻居大哥，到黑龙江插队，他们吃了很多苦，遇到的困难和挫折比我们要多得多，所以我对他们充满敬意，希望这些五零后大哥大姐晚年能够过得好。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"113_邻居大哥去黑龙江.docx","sourceHash":"0b512a137c9233ef1d4250b383b9e619d0817ddd442e51c372a2b6751c437791","chapterNo":7,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-14 15:31:05"},{"id":"jiang-114","title":"两百年霸业","text":"我经历过文化大革命、四人帮倒台、华国锋上任、邓小平复出、拨乱反正、恢复高考、改革开放、下海潮、非典、汶川地震、新冠疫情。\n美国总统也经历了十来个，从尼克松到特朗普。\n总体来说风景东方好，西方走下坡，两百年霸业的那个霸权，已经是风烛残年，和特朗普一样，中国以德为先，胸怀大志，必定取代老朽的霸主，是定局，大势所趋。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"114_两百年霸业.docx","sourceHash":"3603a456287ee31f7671933cf433bab68ffd11883debbff26d8694be509c3626","chapterNo":8,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-14 16:28:42"},{"id":"jiang-115","title":"读约翰克里斯多夫","text":"记得那时候读过全本的《约翰.克里斯多夫》，傅雷译著，水平极高。\n影响很大的电影有《年轻的一代》、《莫让年华付水流》。\n八十年代的青年求知欲比较强，都有为国家民族贡献力量的愿望，因为国家太穷了，老百姓太苦了，要赶上人家只有靠勤奋学习。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"115_读约翰克里斯多夫.docx","sourceHash":"8e4a37ff937faa8daebcf599c894b330a0dd853acf4da6fd64e8bfb46384fafd","chapterNo":8,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-15 09:50:06"},{"id":"jiang-116","title":"数学一直没跟上","text":"学生时代最大的挫折是数学太差了，还连累了物理、化学的学习。\n到高中也没有很大的进步。\n后来物理化学基本跟上了，数学也还是徘徊不前，想放弃又不敢放弃，就这样稀里糊涂的过来了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"116_数学一直没跟上.docx","sourceHash":"d725a4936bb1752653ead6a27a270eb3e497fa9c950eb3981c228fef405b71da","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-15 09:54:37"},{"id":"jiang-117","title":"同桌转学","text":"曾经喜欢过自己的同桌，她漂亮学习又好，脾气也好，不高冷，不像别的女孩子画什么三八线，有很多交谈，发现共同点很多。\n可惜初二她转学了，去了一个更好的学校，再也没有交集，直到三十年后同学会才见到。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"117_同桌转学.docx","sourceHash":"004f0787654d15864af89f9bf4ce84df275c60a56761f1259e223cb6a4101032","chapterNo":2,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-15 10:02:34"},{"id":"jiang-118","title":"尊重孩子选择","text":"现在二十一世纪都过去二十多年了，社会发生了翻天覆地的变化，离婚率也急剧上升，年轻人谋生都不易，选择婚姻更是难上加难。\n不期望他们都能获得美满的姻缘，只期望他们能够身体健康，事业顺利，就可以了。\n我的思想很开明，单身也好，成家也罢，都应该是他们在合适的时候做出来的合适选择，我都尊重孩子们的选择。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"118_尊重孩子选择.docx","sourceHash":"4e29d0459111e320a72cfef01e0bc907e4a9b18ff400a9e8f5b68a6820bf62ae","chapterNo":8,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-15 10:09:12"},{"id":"jiang-119","title":"裸婚也行","text":"只要是对方真的是爱我的孩子，愿意付出真心，我不论任何条件都可以接纳，哪怕是裸婚，也不是不可以。\n像当年我和他们的妈妈谈恋爱的时候几乎都是一无所有，结婚的钱还是慢慢攒起来的，也不是过得很好吗？\n钱，物质，都是次要的，感情才重要。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"119_裸婚也行.docx","sourceHash":"fe3438a4de044750ae009f8fdee364bef34ec2bad0bc8eb821d9a75c7e8aa9e4","chapterNo":8,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-15 10:15:16"},{"id":"jiang-120","title":"零件库规程","text":"就是能记住我为公司编写的一套零件库技术操作规程吧，这是我退休前应领导要求集三十多年的经验写的，只要有用就行了哈哈！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"120_零件库规程.docx","sourceHash":"295931a1e8456ab1ee7b9e6c840ca9754a6570eeec5ecc33a497113284a12dc1","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-15 10:19:25"},{"id":"jiang-121","title":"知足里三根金条","text":"小时候住的地方叫“知足里”，是民国时期的历史建筑，像上海石库门的房子。\n听说是我爷爷在抗战胜利后用三根金条买的，也算是当时的大户人家了吧。\n当时整栋楼都是我们的，二楼出租给了一户上海来的家庭，两家人的关系很融洽，整条弄堂里的居民就像一家人一样，邻里关系和睦，谁家有困难谁都会帮一下，现在是没有这种亲如一家的事情了，社会的变迁让邻里都疏远了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"121_知足里三根金条.docx","sourceHash":"4c001bb1f8c75235a317c622603464ace4c4f84a37e6b7ffc2d4dd1f6937756e","chapterNo":1,"stageId":1,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-15 11:05:47"},{"id":"jiang-122","title":"一年级零蛋","text":"好像是因为一次小学一年级数学考试吃了零蛋被我爸一顿暴打，从此以后对数学发抖的害怕。\n现在看来也是我爸不对，教学方法太粗暴野蛮，我爸这种暴力倾向，很伤害孩子的自尊心，也给我的童年留下了阴影，数学不好成了痼疾。\n我儿子数学考了十来分我都说有进步，对他鼓励很大。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"122_一年级零蛋.docx","sourceHash":"3cc744aacf97066ed0a909349fab1b71f7b30e52ad189a6093714cbc562f2bf2","chapterNo":1,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-15 11:11:47"},{"id":"jiang-123","title":"文革信念崩塌","text":"小时候坚信不疑“文化大革命”，认为领袖挥手我前进就是对的。\n到长大了发现它就是错的，而且还是错得离谱，把老干部、知识分子、爱国商人、小资产阶级都打成了反革命。\n我们在“残酷斗争，无情打击”，“宁要社会主义草也不要资本主义苗”。\n外面的世界是阿波罗登月，日本新干线通车，法国巴黎台方斯潮流街区建成，台湾香港经济起飞。二十世纪七十年代的世界经济腾飞阶段被我们生生的错过了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"123_文革信念崩塌.docx","sourceHash":"17c1898eb3a43f3022e2eaf74debce22295443193e96a6d0f3408bebd2288ba5","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-15 16:44:36"},{"id":"jiang-124","title":"工人中成长","text":"如果有孙辈的话，最希望他们能够读万卷书行万里路，学有所成，报效祖国，和工农相结合。\n我自己是工人当中成长起来的，劳动能够锻炼人，所以他们也要成为有才华，有理想，接地气，脱离象牙塔的知识分子。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"124_工人中成长.docx","sourceHash":"7bf87ed6b8cdf37f495fd477dd6f615ad327b3c2798ea75c451b08617cd599df","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-08-15 16:49:22"},{"id":"jiang-125","title":"关系变冷","text":"八十年代的时候同事朋友家人都是非常亲密的关系，可能是当时红色成分还比较多吧。\n九十年代后就西化多了，人情味也越来越淡薄。\n新世纪以后人们的关系越来越冷漠，这和日韩的发展阶段也差不多。\n时代在变，潮流在变，以后可能会变成超高冷社会，经济越发达人与人之间的关系越来越冷漠，也是正常的。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"125_关系变冷.docx","sourceHash":"28c985b383e330bd98e868fd6de1b5126b73f7e1efe1b595274bb95c24ac49d3","chapterNo":7,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-15 17:09:54"},{"id":"jiang-126","title":"孩子小没旅游","text":"最大的遗憾是在他们小的时候去旅游的机会不多，工作忙，也没时间，收入也不高，直到经济条件好了才带他们出去了几次，很遗憾。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"126_孩子小没旅游.docx","sourceHash":"d4ffe2a7e4ce8273c8bbc5fd9b84cb459507e95c93dec787eeca353e16c04639","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-15 17:21:24"},{"id":"jiang-127","title":"西湖牌收音机","text":"小时候的老物件记忆当中最深刻印象就是客厅里那台西湖牌六灯收音机。\n这台收音机是我爸买的本厂产品，当时叫富春江电讯器材厂。\n这台机器音质特别好，听音乐低音澎湃，听戏曲也清楚。\n右上角还有一个绿色猫眼电子管指示灯显示调谐效果，信号好的话猫眼会全画面拉开屏，像孔雀开屏一样漂亮。\n晚上全家人都会围坐一起听广播。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"127_西湖牌收音机.docx","sourceHash":"61619ed51c289218148db977da2a251d581f01d3f244e4736ae84760ec9e6532","chapterNo":10,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"CHILDHOOD","recordedAt":"2026-08-15 20:14:01"},{"id":"jiang-128","title":"浣纱河没了","text":"我最早的记忆就是那条浣纱河。\n居民洗衣服淘米都是在河边上，大妈大嫂捶打着衣服，说说笑笑。\n现在这条河已经没了。\n当年的浣纱河填平以后，马路上开起来了人防工程改建的经济型旅社“定安旅社”，还有一个东北人来经营的北方水饺店，饺子非常好吃，社区的食堂吃饭也非常便宜……上世纪七十年代初的改革开放已经慢慢开始了，街道工厂，老虎灶（为居民服务的开水供应点），派出\n所……烟火气十足，生活气息浓厚，夏天的夜晚，家家户户把竹躺椅搬出来，大家谈天说地，摇着蒲扇拉家常里短，十分热闹和放松，井水里泡凉的冰镇西瓜十分可口……杭州人度夏是非常的惬意！\n马路上的汽车也越来越多了，有解放牌卡车，跃进牌货车，伏尔加轿车，上海牌轿车，傍晚看汽车是我的暑假爱好哈哈。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"128_浣纱河没了.docx","sourceHash":"b1737c680fbb630fb060d37c1a9180a30feeb6ad47fb998ba3d815e91784d8eb","chapterNo":1,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"CHILDHOOD","recordedAt":"2026-08-15 21:00:22"},{"id":"jiang-129","title":"婚礼前送礼","text":"第一个算正式喜欢的姑娘，是我的同事，长得娇小可爱，能说会道。她喜欢我的知书达理温文尔雅，我喜欢她的外向活泼。\n可惜表白迟到了一步，她和她的夜校同学，年长她八岁的大叔在一起了。她欠我的情意一辈子都还不上了。没办法，她喜欢大叔，我也没死缠烂打，还非常有风度的在她婚礼前送了她礼物。\n她结婚那天晚上我心如刀绞一样，和我的好友们喝酒喝醉了。也好，她喜欢大叔还是放手，这样她欠我的情意就是一生一世。八十年代的人还讲究这个爱情，不计较条件，也不讲金钱，有她这份感情我也很高兴了，虽然没有缘分，但她心里应该还是有我的，也知足了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"129_婚礼前送礼.docx","sourceHash":"10c08e970fd824099757378d01c354f293f938909be79253a86fde6d01e39974","chapterNo":4,"stageId":4,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-16 17:57:20"},{"id":"jiang-130","title":"七十岁浙大教授","text":"官员，商人，无业人员，我绝不会结交，不是同一类人，也没有共同语言。\n我的朋友当中，教师，医生，职工，占了绝大多数。他们和我人生经历相近，也很聊得来。\n我还有很多忘年交，有比我年长的，也有年轻的。最年长的一位是七十多岁的浙大老教授。从朋友当中你可以吸收人生智慧，得到友情的滋养，很快乐。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"130_七十岁浙大教授.docx","sourceHash":"90762d6d755d4fea0dba04b25b45af5c9979013d6731bf2f5959980de25e1b21","chapterNo":7,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-17 09:19:55"},{"id":"jiang-131","title":"胶片初试","text":"胶片摄影是去年买的一部二手尼康F70胶片单反相机开始的，从网店买了一卷国产乐彩C200彩色胶卷，去西湖一公园拍了一套风光，取出来胶卷暗盒寄到深圳一家图片社冲扫，第一次试水合作，等了十来天才拿到照片文件。\n谢天谢地没有一张废片，看来我的技术没有问题哈哈，胶片摄影就是这样有仪式感和期待感，比数码更有工业时代的味道，画面色彩也比数码更厚重更复古，就是成本高，没办法，数码摄影就是比胶片性价比高，所以胶片摄影也只能是小众消费了，时代变了，谁不喜欢不用\n花钱就能得到底片的数码相机呢，只是希望胶片摄影这种古早艺术还是能存在就很满足了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"131_胶片初试.docx","sourceHash":"d1999eb00ac6c969ff1b577bf00e3e3178ab69f042365ad85512c8d10c96c8eb","chapterNo":8,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-17 10:36:52"},{"id":"jiang-132","title":"温情教育观","text":"在他们的成长过程中我一直都是采取宽松而又温柔的教育方式，从来没有暴力体罚过。\n希望他们也能够在有了自己的孩子以后，也不要用简单粗暴的方法解决教育孩子上的问题，要讲道理，以理服人，而不能一味信奉‘棒打出孝子’这样的观念，不然你收获的不是孝子，而是敌人，这对于孩子来说是极大的打击和伤害。\n温情教育，理性认识，才是上策。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"132_温情教育观.docx","sourceHash":"46ede05d93b2e26227765fa5057a950a57d71ecaa3f90ea496a62d12bc766e46","chapterNo":5,"stageId":6,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-18 20:25:35"},{"id":"jiang-133","title":"1978年夏做香肠","text":"记得在南山中学读书的时候，1978年夏，学校组织各班级去校办工厂学工劳动做香肠，我分在切肉组，负责分切鲜肉。\n当时的流水线分切肉，剔骨，灌肠衣，扎眼，排钉等工序，每个同学身穿蓝色大褂工装，在组长的领导下学工劳动，车间里非常热，噪声也很大，但大家的劳动热情高涨。\n我们的产品质量也很好，生产的香肠味道鲜美，香气四溢，当时都是真材实料做的，正宗白酒和优质肠衣，让我们的产品非常的畅销。\n愉快的学工劳动结束后，学校还每人发了几斤香肠和小点心带回家，我爸妈都夸奖我们的香肠做得好！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"133_1978年夏做香肠.docx","sourceHash":"594b96097820dd8bea738a74020469b17a8eaf1341b5a2e9eca1e71539e6958b","chapterNo":1,"stageId":3,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"EDUCATION","recordedAt":"2026-08-19 09:34:53"},{"id":"jiang-134","title":"省人民大会堂看《追捕》","text":"1978年的日本电影周，以影片《追捕》为龙头轰动了全国。高仓健演的帅气、勇敢、执着的检察官杜丘，秉承法律的尊严，坚定不移的追寻真凶的男子汉形象，征服了中国观众的心。\n影片里的高楼大厦，车水马龙的繁华东京，衣着入时的日本青年男女，拥有私人飞机的农场主远波先生的豪华庄园……让我们这些刚刚从文革一片荒芜中走出来的年轻人看得瞠目结舌。\n我是在省人民大会堂看的电影。外面的世界和我们简直就是在两个星球上，太震撼了！\n那一年大街上最流行的就是杜丘太阳镜，也叫蛤蟆镜，男孩子戴一副蛤蟆镜（进口商标还舍不得撕下来），穿一条喇叭裤，拎一台日本三洋牌四喇叭收录机，你就是大街上最靓的仔。\n这个形象现在看起来也不太过时，哈哈哈，太有意思了，和国际接轨，是那个年代最生动的注脚。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"134_省人民大会堂看《追捕》.docx","sourceHash":"03f1f4efd4bdb82cd4758662a73f0ac6e154c9b3a47d896ab6a279ed6f58cfdb","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-20 10:26:39"},{"id":"jiang-135","title":"丧母又丧偶","text":"我最大的苦难就是丧母和丧偶，生命中两个至亲的人都早逝，的确是留下来了很深的伤痕。\n刚刚有了孩子的时候母亲早逝，孩子刚刚长大即将踏入高中的时候又丧偶，的确是生活中的重大打击，迈过这两个坎的确是花了很长时间的。没办法。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"135_丧母又丧偶.docx","sourceHash":"df41593eab3ff929c1819a24776aa59865ed48165c7b861a52e6137fc33b7184","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-20 20:44:10"},{"id":"jiang-136","title":"防震棚夏夜","text":"1976年的唐山大地震，在我的记忆中也是非常的震撼，蓝光闪过之后，一座百万人口的工业城市瞬间变成一片瓦砾，死伤人口无数，连市委班子领导都伤亡了好几个，北京卫戍区、驻天津部队，紧急派出了救援部队和民兵赶往灾区救援，有很多伤员被送往全国各地治疗\n。\n76年夏天我们全家也都被社区要求住外面空地上搭的防震棚，孩子们都怕蓝光，对地震的恐惧是实实在在的体验。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"136_防震棚夏夜.docx","sourceHash":"7cde8123b5727e3da4833ca60492730f895c4c71c547237011bd9f1552a2905c","chapterNo":6,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-21 14:19:28"},{"id":"jiang-137","title":"妈妈和太太离世","text":"至亲离世当然是经历过的，我妈妈和我太太，一生中最重要的两个亲人离去。\n我妈妈离世是六十多岁，我太太离世是四十多岁，都太早了，主要是疾病太凶险，也没办法……\n现代医学尽管已经很先进但面对这种恶性疾病还是没有什么有效的办法，希望人工智能的出现和发展能够为凶险疾病患者带来生命的希望，解决医学的局限性问题。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"137_妈妈和太太离世.docx","sourceHash":"22d66c6bb237e4b09d201e45fe26ddce1c72c8cd6b5599eacb4f6bc147cbf231","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-21 15:09:08"},{"id":"jiang-138","title":"王心刚来弄堂","text":"二十世纪七十年代的时候，电影界最好看的明星男有王心刚，女有王晓棠，男的俊美高大，女的秀美温柔，他俩就是我们的心中偶像。\n没想到1975年秋的一天，他俩真的来到了知足里二弄来探望老朋友，我在弄堂口看到身穿军装的他俩真的是漂亮，王心刚叔叔送了我一张签名照和一卷《闪闪的红星》电影胶片，欢喜得不得了，哈哈……\n后来搬家这些珍贵的留念物品都没有了，可惜呀！王心刚先生至今还健在，九十多岁了，祝老人家健康长寿！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"138_王心刚来弄堂.docx","sourceHash":"fe56801106ef15fae9651966cabd4313e0eb7ac2a9d44637c11a6b9f1960bdf5","chapterNo":8,"stageId":2,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-23 13:17:40"},{"id":"jiang-139","title":"三不管爷爷","text":"做祖辈我还早呢，但是从我爸妈当爷爷奶奶外公外婆的经验看，隔代溺爱是不能有的，不然会影响以后孩子的成长和性格。\n祖父母辈也不能介入自己子女对孩子的教育和管理，毕竟他们是父母不是你，你只是帮助他们照看一下而已。\n另外也不能把自己的育儿观念强加给自己的孩子，年轻人的想法和你祖父母肯定是不一样的。\n我要当爷爷外公的话，就做一个三不管爷爷外公吧，哈哈哈！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"139_三不管爷爷.docx","sourceHash":"34cbc4608be6c748a20b2bf29c877f6c1db251cb735ae1ecfb3e94a98e8ee8b7","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-26 21:08:43"},{"id":"jiang-140","title":"五仁月饼","text":"最不喜欢吃的就是五仁月饼，哈哈，原因嘛众所周知哈哈哈。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"140_五仁月饼.docx","sourceHash":"7f8ec6c69c349a140fd7d3beee506833a54e8b1993d7f47a5684b8dcecf81816","chapterNo":10,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-26 21:14:38"},{"id":"jiang-141","title":"大舅援越记","text":"1964年到1975年，中国人民解放军曾经派出几十万部队到越南支援抗美援援战争，我的大舅施伯铭少校也在其列，作为中国军事顾问团的成员为越南军民提供军事斗争经验。\n他曾被胡志明主席和武元甲大将亲切接见，美军在越南战场上被中国军队揍得落花流水，美国飞机被解放军高炮部队打得空中开花。\n美军没那么可怕，碰到毛泽东思想武装起来的解放军，就是败军败将，美国飞行员都不敢飞进中国高炮部队防御圈。\n尼克松之所以主动来找毛主席握手，就是被解放军打怕了，想求中国帮助他摆脱越战的泥潭，美国人欺软怕硬的本性就是这样。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"141_大舅援越记.docx","sourceHash":"ee6f7529084be07e0d561c4f2a78a31609d828df18efa7f3948219ca36c36b26","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"RELATIVES","recordedAt":"2026-08-27 10:36:38"},{"id":"jiang-142","title":"泥石流科教片","text":"西藏吉隆口岸泥石流灾难很痛心，那么多人遇难，泥石流是破坏性非常强的自然灾害。\n上世纪七十年代的时候上海科教电影制片厂曾经拍过一部很好看的科教片《泥石流》，在全国上映过，形象的向广大人民群众介绍了泥石流的危害，以及防灾减灾救灾的科学知识，大家都很受教育。\n现在电影行业利润至上，这种科教电影都没有人愿意拍了，这也是艺术的悲哀，科教片不赚钱，但是它有普及科学知识，宣传防灾减灾的功能，这个片种没了，损失是不是更大?","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"142_泥石流科教片.docx","sourceHash":"0040b6f3e469f0c94d15e089392a266a1d5331f749c1c99f0e81837d7a2f1398","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"","recordedAt":"2026-08-30 13:12:06"},{"id":"jiang-143","title":"家常豆腐","text":"最能代表家的味道的菜就是家常豆腐，老豆腐加上酱油，糖，味精，蒜苗，翻炒出锅，加一点点蚝油调味。\n这一口豆腐就是妈妈的味道，哈哈！","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"143_家常豆腐.docx","sourceHash":"ad0d23187b0edeaa6979dd3424abf6bd98dd3422ab22c73868808da08131b636","chapterNo":10,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-30 20:19:50"},{"id":"jiang-144","title":"会说多种方言","text":"我杭州方言和普通话，上海话，都会一点，可能是有点语言天赋吧，英语日语也会一点，哈哈。\n我喜欢和朋友一起聊天，喜欢热闹的氛围，聊天特别开心。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"144_会说多种方言.docx","sourceHash":"c85e048be2da69a1b94846d4cb672b5c897ad63d5b245a2adf710fb541ba5941","chapterNo":10,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-31 19:26:53"},{"id":"jiang-145","title":"拍桌子而已","text":"再生气也只是拍桌子而已。\n我不喜欢大吵大闹，没什么意思。\n由于儒家文化的熏陶，我始终是一个内敛的人。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"145_拍桌子而已.docx","sourceHash":"39a49187afb3bc482006042e3495daa61c8cd0ff2395bb876cc4f0be6c9b1cd9","chapterNo":6,"stageId":8,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-31 19:29:52"},{"id":"jiang-146","title":"八月桂花香","text":"记忆中最好闻的味道当然就是杭州的市花桂花香了。\n八月桂花香是美丽杭州的代表性记忆，老市长苏东坡都曾经赞不绝口杭州的桂花。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"146_八月桂花香.docx","sourceHash":"ce570148fed52c3a7878fe1a2e09b78c6c24d14006d49195fea9a17c1019786a","chapterNo":10,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-31 19:33:31"},{"id":"jiang-147","title":"会唱二三十首","text":"我会唱的歌很多，大概有二三十首吧。\n最喜欢的歌有《一剪梅》，《莫斯科郊外的晚上》，《我的中国心》。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"147_会唱二三十首.docx","sourceHash":"b84dbb9a159238502cc22608a94ff93a8bff1fd6df30ec4c84458c583fe2bd0d","chapterNo":10,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"BIRTH_FAMILY","recordedAt":"2026-08-31 19:37:43"},{"id":"jiang-148","title":"放飞和平鸽","text":"那当然是我和小芬举行的婚礼现场了。\n两场婚礼终生难忘，中式婚礼古朴典雅，西式婚礼大气华丽，各有各的特色。\n记忆特别深刻的是我们两个人一起放飞和平鸽。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"148_放飞和平鸽.docx","sourceHash":"e9e0a6bc5e0f2a505fc6fe3c6dc2ae4a7e4056288d8b35181d058dad2db53a3e","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-08-31 19:42:50"},{"id":"jiang-149","title":"小芬冒雨赴约","text":"记得有一次和小芬谈恋爱的时候约好看电影，她迟到了半个小时才来，那天晚上下大雨，她的鞋都湿透了，事后才得知在雨中她差点被汽车撞到了，幸好没事。\n我第一反应就是抱住她安抚她瑟瑟发抖的身体。\n她下班急着赶路到电影院，她对约会的重视让我动容，这么老实巴交的姑娘难道不值得我爱吗？","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"149_小芬冒雨赴约.docx","sourceHash":"7c7b12e5407ddca004751329054324e29d43ffb0acfc8109a9411791b94210c3","chapterNo":4,"stageId":5,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"MARRIAGE","recordedAt":"2026-09-09 22:10:18"},{"id":"jiang-150","title":"国产CT球管梦","text":"从17岁高中毕业到退休，我在电真空器件制造行业整整工作了将近四十年，对这个行业还是非常热爱的，退休以后也还在关注着这个行业的动态。\n作为国产X射线管的亲手制作人，我们有一个共同的梦想就是想快点看到全国产自有知识产权的高端大热容量CT球管的诞生与成熟，这颗电真空器件的皇冠上的明珠，现在还没有瓜熟蒂落，是我们老技工的一块心病。\n国家每年要花大笔外汇进口球管，而且还被外国人拿捏在手里，万一哪天被人卡脖子就麻烦了。\n如果能够突破材料和零部件瓶颈，依托现有资源是可以做出来高端产品的，希望后辈们能够加快速度研发，解决高端特种金属靶盘和液态高速轴承的自主生产问题，那实现高端CT球管自给自足就不是梦了，装配工艺和技术不成问题，当年我们那么艰苦的条件都做出来了旋\n转阳极管，现在更可以了。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"150_国产CT球管梦.docx","sourceHash":"90a627c32c6a79cbfde9b2b2458cf484bdc1aee8522bd3ebd2b1e7c243f16048","chapterNo":9,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-10-01 11:46:55"},{"id":"jiang-151","title":"电子管厂退休聚","text":"电子管厂退休职工欢乐聚，今年已经是第四届了。\n第一届我还在上班没有参加，从第二届开始我都是担任工作人员。\n我负责音响调音和视频播放，操作计算机对我来说没有什么难度，驾轻就熟游刃有余。\n音响有一点难度的，因为每个场地的设备都不一样，要和对方的音响师傅对接学习，每次都是新的设备，新的技术，新的流程，效果也都不一样。","kind":"user","caseId":"jiang-teacher","origin":"客户提供的 Word 故事卡","sourceFile":"151_电子管厂退休聚.docx","sourceHash":"7c6c58b954fdf5cca68c355451cca6d1f9ae9704147951c1f8301fbd6e443819","chapterNo":7,"stageId":7,"classificationStatus":"case_editorial_pending_confirmation","originalCategoryCode":"WORK","recordedAt":"2026-10-30 09:26:19"}],"lifeScenes":[{"title":"浣纱河边的童年","sourceIds":["jiang-128","jiang-127","jiang-037"],"narration":"我最早的记忆，是家门口那条浣纱河。大妈大嫂在河边洗衣服、淘米，说说笑笑。夏天，大家把竹躺椅搬出来，摇着蒲扇聊天，井水里泡凉的西瓜，吃起来特别舒服。家里有一台西湖牌六灯收音机，绿色的猫眼指示灯一亮，全家就围着听广播。奶奶每周给我八分钱，我一个人去新华电影院看电影。那时候哪里会想到，看电影这个爱好，会陪我这么多年。","action":"以浣纱河生活的叙述与收音机细节构想开场；缺少实景资料时仅呈现文字，不拿其他城市冒充旧杭州。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"学校之外，继续读书","sourceIds":["jiang-013","jiang-022","jiang-030"],"narration":"没有参加高考，是我一直记着的遗憾。我偏文科，理科不太好，高中读完就参加工作了。但上了班，书也没有放下。白天在厂里干活，晚上骑车去钱江业余学校上英语课，一读就是三年。后来做质量管理，学那些新概念，开始也像听天书，只好从名词解释一点点啃。考试过了，自己的卷子还被经理拿去作标准答案。读书苦，但苦得有价值就好。","action":"夜校书本、自行车与学习笔记的画面构想；证书必须使用对应原件，不能生成虚构奖状。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"把一门手艺学到手","sourceIds":["jiang-006","jiang-044","jiang-045","jiang-103"],"narration":"进杭州电子管厂以后，我从三车间的排气操作工做起。学烧玻璃，师傅示范得很熟练，轮到我，满头大汗也做不好。我就多练，练到烧破了三条裤子，烫伤一个手指头，才慢慢摸到了门道。后来做质量工作，又跟着师傅学读图，把图纸和零件一一对起来。直到现在，一看到图纸，阴极套、阳极帽的样子还会出现在脑子里。我们做的电子管，有的到今天还在发挥作用，想到这里，心里是有一点骄傲的。","action":"先展示原故事卡附带的杭州牌电子管产品图；烧玻璃操作仅作待核对构想，不把产品照片指认为本人当年制作的那一只。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"小芬来到我家","sourceIds":["jiang-008","jiang-067","jiang-068","jiang-069","jiang-149"],"narration":"过了三十岁，爸妈为我的婚事着急。后来，妈妈托小姐妹介绍，小芬来家里见面。她穿着西服套装，笑得自然，和我妈聊着天，我心里就觉得，就是她了。谈恋爱的时候，我们喜欢手牵手逛庆春东路的夜市，买件衣服、买副耳机，都是开心的事。有一回约好看电影，她迟到了半个小时，鞋子全湿了。我后来才知道，她在雨里赶路，差一点被车撞到。我抱着她，先让她缓过来。等结婚的钱攒够了，我们就去登记。没有什么求婚仪式，就是这样简单。","action":"夜市、雨鞋与登记材料可作为画面构想；尚无已核对的小芬肖像，不使用陌生人物示例。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"两个人，把一家人照顾好","sourceIds":["jiang-012","jiang-035","jiang-051","jiang-064","jiang-110"],"narration":"有了龙凤胎以后，日子忙了许多。小芬操心家务、衣服和日用品，我多操心孩子的学习，各自做自己擅长的事。孩子小的时候，我总想把他们牵在手里。后来小芬提醒我，他们总归是要长大的，我才学着放手。女儿喜欢艺术，儿子喜欢电脑，我不想把自己的想法全压给他们。女儿后来学产品设计，儿子学建筑工程技术，都挺好。想起小时候，我和妹妹穿的毛衣，都是妈妈一针一针织的。家人对一个家的照顾，我一直记得。","action":"母亲故事使用064原卡合影作回忆资料，保持完整画幅；不把合影当作妻子或孩子照片，不凭服装猜身份。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"有些想念，留在心里","sourceIds":["jiang-007","jiang-071","jiang-105","jiang-135","jiang-137"],"narration":"母亲和小芬的离开，是我人生里最难迈过去的两道坎。小芬病倒以后，手术后的恢复不好，没过多久就走了。那些日子很难，生活还是要一点点往前过。如今想起来，过去工作太忙，陪家人的时间实在少了。现在，我想多陪陪孩子和老爸。如果能回到刚恋爱的时候，我想给小芬补一个求婚仪式，补上一束花。可惜她已经不在了。我永远怀念她。","action":"用经核对的家庭旧物或留白承接旁白；不补拍病床、临终告别、遗言或实际发生的求婚。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"还想拍一辈子西湖","sourceIds":["jiang-019","jiang-041","jiang-089","jiang-036"],"narration":"退休以后，有空我就带着相机去西湖走走。拍一拍四季，累了找地方歇歇脚，吃点东西，很舒服。我从前拿相机给小芬拍、给孩子拍，如今也慢慢收藏起相机。西湖一年四季都有它的美，我打算拍一辈子西湖。说了这么多，我也只是个普普通通的人。有遗憾，也有值得记住的日子。把这些经历留下来，让后辈知道我们怎样走过来，就是我写回忆录的目的。","action":"使用089原卡西湖照片，019原卡相机资料图；以湖景停留收尾，不添加虚构团聚场面。","setting":"按故事原文；具体年份与人物造型待核对"}],"fragmentScenes":[{"title":"浣纱河边的童年","sourceIds":["jiang-128","jiang-127","jiang-037"],"narration":"我最早的记忆，是家门口那条浣纱河。大妈大嫂在河边洗衣服、淘米，说说笑笑。夏天，大家把竹躺椅搬出来，摇着蒲扇聊天，井水里泡凉的西瓜，吃起来特别舒服。家里有一台西湖牌六灯收音机，绿色的猫眼指示灯一亮，全家就围着听广播。奶奶每周给我八分钱，我一个人去新华电影院看电影。那时候哪里会想到，看电影这个爱好，会陪我这么多年。","action":"以浣纱河生活的叙述与收音机细节构想开场；缺少实景资料时仅呈现文字，不拿其他城市冒充旧杭州。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"学校之外，继续读书","sourceIds":["jiang-013","jiang-022","jiang-030"],"narration":"没有参加高考，是我一直记着的遗憾。我偏文科，理科不太好，高中读完就参加工作了。但上了班，书也没有放下。白天在厂里干活，晚上骑车去钱江业余学校上英语课，一读就是三年。后来做质量管理，学那些新概念，开始也像听天书，只好从名词解释一点点啃。考试过了，自己的卷子还被经理拿去作标准答案。读书苦，但苦得有价值就好。","action":"夜校书本、自行车与学习笔记的画面构想；证书必须使用对应原件，不能生成虚构奖状。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"把一门手艺学到手","sourceIds":["jiang-006","jiang-044","jiang-045","jiang-103"],"narration":"进杭州电子管厂以后，我从三车间的排气操作工做起。学烧玻璃，师傅示范得很熟练，轮到我，满头大汗也做不好。我就多练，练到烧破了三条裤子，烫伤一个手指头，才慢慢摸到了门道。后来做质量工作，又跟着师傅学读图，把图纸和零件一一对起来。直到现在，一看到图纸，阴极套、阳极帽的样子还会出现在脑子里。我们做的电子管，有的到今天还在发挥作用，想到这里，心里是有一点骄傲的。","action":"先展示原故事卡附带的杭州牌电子管产品图；烧玻璃操作仅作待核对构想，不把产品照片指认为本人当年制作的那一只。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"小芬来到我家","sourceIds":["jiang-008","jiang-067","jiang-068","jiang-069","jiang-149"],"narration":"过了三十岁，爸妈为我的婚事着急。后来，妈妈托小姐妹介绍，小芬来家里见面。她穿着西服套装，笑得自然，和我妈聊着天，我心里就觉得，就是她了。谈恋爱的时候，我们喜欢手牵手逛庆春东路的夜市，买件衣服、买副耳机，都是开心的事。有一回约好看电影，她迟到了半个小时，鞋子全湿了。我后来才知道，她在雨里赶路，差一点被车撞到。我抱着她，先让她缓过来。等结婚的钱攒够了，我们就去登记。没有什么求婚仪式，就是这样简单。","action":"夜市、雨鞋与登记材料可作为画面构想；尚无已核对的小芬肖像，不使用陌生人物示例。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"一家人的照顾","sourceIds":["jiang-012","jiang-035","jiang-051","jiang-064"],"narration":"龙凤胎小时候，抚养很不容易，节衣缩食，也慢慢长大了。我原来总要把孩子牵在手里，上小学以后，小芬提醒我，他们总归是要长大的。我开始学着放手。女儿喜欢艺术，儿子喜欢电脑，就让他们向喜欢的方向走。想起我的小时候，我和妹妹的毛衣都是妈妈亲手织的。她照顾我们，我们再照顾自己的孩子，这些平常日子，我都记在心里。","action":"使用064母亲故事卡合影作资料参考；孩子照片另待核对。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"把日子往前过","sourceIds":["jiang-007","jiang-105","jiang-135","jiang-137"],"narration":"母亲和小芬的离开，让我难过了很长时间。小芬病倒后，手术恢复得不好，没多久就离开了。办完后事，日子还是要过，孩子也在慢慢长大。回头看，我过去工作忙，陪家人的时间很少。现在就想多陪陪孩子和老爸。","action":"保留叙述空间，不虚构临终画面和具体疾病名称。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"西湖和相机","sourceIds":["jiang-019","jiang-041","jiang-089","jiang-036"],"narration":"退休以后，有空我就带着相机去西湖走走。拍一拍四季，累了找地方歇歇脚，吃点东西，很舒服。我从前拿相机给小芬拍、给孩子拍，如今也慢慢收藏起相机。西湖一年四季都有它的美，我打算拍一辈子西湖。说了这么多，我也只是个普普通通的人。有遗憾，也有值得记住的日子。把这些经历留下来，让后辈知道我们怎样走过来，就是我写回忆录的目的。","action":"使用089原卡西湖照片，019原卡相机资料图；以湖景停留收尾，不添加虚构团聚场面。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"一阵风过去以后","sourceIds":["jiang-040"],"narration":"那一回台风夜，全家刚过完妹妹的生日。凌晨，风雨把我们惊醒，阳台玻璃震碎了，我和妹妹顶住阳台门，爸爸拿胶带来封。第二天，大树倒在路上，车也坐不成，我走了一个多小时去上班。后来，大家一起去西湖边救树，好几天才缓过来。","action":"以风雨声和静物构想表达，不使用别处灾害影像冒充当年的家。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"西湖边的第一份工作","sourceIds":["jiang-001","jiang-084"],"narration":"刚离开学校，我托爸妈找了一份临时工作，在西湖边的食品商店卖糖果。俞师傅是劳模，教我技术，忙起来也过来帮忙。带孩子的顾客来了，我喜欢逗逗小朋友。糖果给他们带去欢乐，自己干着也开心。三个月后，我要去做另一份工作，离开时很舍不得。商店后来没有了，这段甜蜜的工作，我还记得。","action":"食品柜台构想，不编商店名，不添加虚构人物对白。","setting":"按故事原文；具体年份与人物造型待核对"},{"title":"登记与想念","sourceIds":["jiang-069","jiang-070","jiang-071","jiang-111"],"narration":"我们把结婚的钱攒够了，就去登记，没什么求婚仪式。新婚的日子很简单，上班，回家做饭，看看电视，或者一起去超市逛逛。两个人也会有分歧，但说好了吵架不过夜，有事好好商量。如今要是能重来，我想补一个求婚仪式，补上一束花。可惜小芬已经不在了，我永远怀念她。","action":"不把愿望拍成已经发生的求婚；人物旧照待提供。","setting":"按故事原文；具体年份与人物造型待核对"}],"notes":["依选中故事卡按人生脉络重组，未按短片时长删减；原文观点和不确定说法保留。","出生、入厂年龄、退休年限以及部分求学年份待本人核对，不擅自替客户改正。","部分故事卡横跨多个阶段；展示按主要叙述分组，不把分组当作精确年份。","当前为真实原文整理预览，未调用实时 AI。"],"roles":["我","小芬","母亲","父亲","女儿","儿子","妹妹","奶奶","师傅"],"deferredSources":[{"sourceId":"jiang-096","reason":"原文只有对数字纪念的简短回应，缺少具体经历，不扩写为人生事件。"}],"chapters":[{"title":"出生与浣纱河边的家","sourceIds":["jiang-002","jiang-011","jiang-121","jiang-128","jiang-127","jiang-025"],"transition":"回头说起这一生，我想先从小时候住过的地方说起。"},{"title":"父母留给我的东西","sourceIds":["jiang-004","jiang-086","jiang-064","jiang-039","jiang-143","jiang-066","jiang-141"],"transition":"说起家里的人，我记着父母各自的样子，也记着他们留给我的影响。"},{"title":"上学的日子","sourceIds":["jiang-055","jiang-003","jiang-122","jiang-043","jiang-085","jiang-013","jiang-056","jiang-029","jiang-082","jiang-116","jiang-117","jiang-133"],"transition":"求学的那些年，有值得高兴的事，也有一直留在心里的遗憾。"},{"title":"电影和音乐，打开一扇窗","sourceIds":["jiang-037","jiang-020","jiang-063","jiang-038","jiang-065","jiang-079","jiang-138","jiang-016","jiang-134","jiang-115"],"transition":"说到年轻时怎样认识外面的世界，电影、音乐和书，都在我的回忆里。"},{"title":"西湖边的第一份工作","sourceIds":["jiang-001","jiang-084"],"transition":"离开学校，走上工作岗位，是人生里另一个重要的开始。"},{"title":"从学徒开始","sourceIds":["jiang-006","jiang-044","jiang-057","jiang-014","jiang-045","jiang-005","jiang-031","jiang-022","jiang-018","jiang-053"],"transition":"说起工作，我想讲讲手艺是怎样一点点学来的。"},{"title":"在工厂里成长","sourceIds":["jiang-015","jiang-026","jiang-075","jiang-062","jiang-046","jiang-058","jiang-091","jiang-092","jiang-021","jiang-032","jiang-103"],"transition":"关于工厂，我记着自己的岗位，也记着和大家一同经历的变化。"},{"title":"日子里的变化和意外","sourceIds":["jiang-076","jiang-040","jiang-007"],"transition":"往前走的这些年，生活也有变化，有高兴，也有难处。"},{"title":"学着适应新的工作","sourceIds":["jiang-047","jiang-048","jiang-030","jiang-017","jiang-049","jiang-054","jiang-120","jiang-150"],"transition":"工作里的变化，让我一次次重新学习，也留下了自己的牵挂。"},{"title":"遇见小芬","sourceIds":["jiang-129","jiang-008","jiang-067","jiang-068","jiang-149"],"transition":"说起小芬，我想把我们相识相处的日子，多留下一些。"},{"title":"我们的小家","sourceIds":["jiang-069","jiang-148","jiang-107","jiang-070","jiang-109","jiang-111","jiang-110"],"transition":"两个人过日子，许多记得最清楚的，都是平常的小事。"},{"title":"孩子来到身边","sourceIds":["jiang-087","jiang-012","jiang-052","jiang-106","jiang-108"],"transition":"孩子的到来，给家里添了欢乐，也添了要学着承担的事情。"},{"title":"学着放手，陪他们长大","sourceIds":["jiang-035","jiang-051","jiang-088","jiang-132","jiang-009","jiang-118","jiang-119","jiang-139","jiang-124"],"transition":"说到孩子的成长，我也在慢慢学着怎样做父亲。"},{"title":"一家人的旅行","sourceIds":["jiang-078","jiang-050","jiang-126","jiang-080"],"transition":"一家人在一起的日子，有些出门走走的经历，我一直记得。"},{"title":"留在心里的想念","sourceIds":["jiang-135","jiang-137","jiang-071","jiang-105","jiang-097"],"transition":"有些回忆说起来不容易，但它们同样是人生的一部分。"},{"title":"告别岗位，仍惦记老朋友","sourceIds":["jiang-077","jiang-083","jiang-151","jiang-027","jiang-102","jiang-130","jiang-144"],"transition":"说到后来，我也想讲讲工作之外的生活和那些朋友。"},{"title":"带着相机去西湖","sourceIds":["jiang-019","jiang-074","jiang-131","jiang-089","jiang-041","jiang-059","jiang-146"],"transition":"西湖和摄影，是我愿意一直聊下去的话题。"},{"title":"把日子过得有滋味","sourceIds":["jiang-033","jiang-060","jiang-072","jiang-099","jiang-098","jiang-147","jiang-140"],"transition":"如今，读书、电影、音乐，还有生活里的小趣味，都陪着我。"},{"title":"我所经历和理解的时代","sourceIds":["jiang-010","jiang-034","jiang-061","jiang-101","jiang-081","jiang-136","jiang-028","jiang-042","jiang-023","jiang-024","jiang-073","jiang-090","jiang-095","jiang-100","jiang-104","jiang-112","jiang-113","jiang-114","jiang-123","jiang-125","jiang-142","jiang-145"],"transition":"回忆里还有我对时代的感受和看法。这些话，带着我自己的经历和认识。"},{"title":"把经历留下来","sourceIds":["jiang-093","jiang-094","jiang-036"],"transition":"最后，还是想说说，我为什么要把这些经历写下来。"}]};const catalog=typeof module==='object'&&module.exports?require('./memoir-catalog.js'):r.YunyiMemoirCatalog;data.sources=data.sources.map(catalog.normalize);if(typeof module==='object'&&module.exports)module.exports=data;else r.YunyiJiangCase=data;})(typeof globalThis!=='undefined'?globalThis:this);
